UPDATE topic_catalog SET pregenerated_json = '{"story_id": "rahu_ketu_origin", "title": "राहु और केतु का जन्म", "category": "ज्योतिष कथा", "script_hi": "राहु और केतु का जन्म कैसे हुआ? समुद्र मंथन के दौरान जब धन्वंतरि वैद्य अमृत कलश लेकर प्रकट हुए, तो देवताओं और असुरों में हाहाकार मच गया। असुर अमृत पीकर अमर न हो जाएं, इसलिए भगवान विष्णु ने मोहिनी रूप धारण किया। मोहिनी ने अपनी माया से अमृत सिर्फ देवताओं को पिलाना शुरू किया। लेकिन स्वर्भानु नाम का एक चालाक असुर यह चाल समझ गया। उसने अपना रूप बदला और चुपके से देवताओं की पंक्ति में जाकर सूर्य और चंद्र देव के बीच बैठ गया। जैसे ही मोहिनी ने उसे अमृत पिलाया, सूर्य और चंद्र ने उसे पहचान लिया और भगवान विष्णु को बता दिया। विष्णु जी ने तुरंत अपना सुदर्शन चक्र निकाला और स्वर्भानु का सिर धड़ से अलग कर दिया। लेकिन अमृत की कुछ बूंदें उसके गले से नीचे उतर चुकी थीं, इसलिए वह मरा नहीं। उसका सिर राहु कहलाया और धड़ केतु। कहते हैं आज भी राहु और केतु इसी धोखे का बदला लेने के लिए सूर्य और चंद्र को निगलने की कोशिश करते हैं, जिसे हम सूर्य और चंद्र ग्रहण कहते हैं। यही कारण है कि ज्योतिष में इन्हें छाया ग्रह और रहस्य का प्रतीक माना जाता है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "राहु और केतु का जन्म कैसे हुआ?", "image_prompt": "Cinematic wide shot of Rahu and Ketu floating in the cosmos as dark shadow planets, dark mystical aura, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "समुद्र मंथन से जब अमृत निकला...", "image_prompt": "Gods and demons churning the cosmic milky ocean, golden Amrita pot glowing, epic mythological lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "विष्णु जी ने मोहिनी रूप धारण किया।", "image_prompt": "Lord Vishnu taking the form of beautiful Mohini holding the golden pot of nectar, divine glow, ancient Indian art style, 9:16", "approx_sec": 6.0}, {"slide_index": 4, "caption": "स्वर्भानु नाम का असुर चाल समझ गया।", "image_prompt": "A cunning demon Swarbhanu looking suspiciously at Mohini, dark background, intense eyes, realistic myth art, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "वह सूर्य और चंद्र के बीच बैठ गया।", "image_prompt": "Demon in disguise sitting between Surya (Sun God) and Chandra (Moon God), glowing deities, tension, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "सूर्य और चंद्र ने उसे पहचान लिया!", "image_prompt": "Sun and Moon gods looking shocked and pointing fingers at the disguised demon, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "विष्णु जी ने सुदर्शन चक्र चलाया...", "image_prompt": "Lord Vishnu angrily throwing the spinning, fiery Sudarshana Chakra, intense action, sparks flying, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "और स्वर्भानु का सिर धड़ से अलग कर दिया।", "image_prompt": "The glowing Sudarshana Chakra slicing through the neck of the demon, cosmic background, mythological drama, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "लेकिन वह अमृत पी चुका था।", "image_prompt": "The severed head of the demon glowing with the power of immortal nectar, starry night sky, eerie, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "सिर राहु बना और धड़ केतु।", "image_prompt": "One floating demonic head (Rahu) and one headless serpent body (Ketu) floating in space, astrology concept, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "आज भी वह सूर्य-चंद्र को निगलने की कोशिश करते हैं।", "image_prompt": "A massive shadow demon trying to swallow the glowing sun, solar eclipse happening in the background, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "जिसे हम ग्रहण कहते हैं।", "image_prompt": "A beautiful but eerie total solar eclipse viewed from ancient India, dark silhouette, cosmic, 9:16", "approx_sec": 4.0}]}' WHERE id = 'rahu_ketu_origin';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "gita_karma_yoga", "title": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ", "category": "श्रीमद्भगवद्गीता", "script_hi": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ क्या है? कुरुक्षेत्र के युद्ध में जब अर्जुन ने अपने ही सगे-संबंधियों को सामने देखा, तो वह टूट गए। उनके हाथ से गांडीव धनुष गिर गया। तब भगवान श्री कृष्ण ने उन्हें गीता का उपदेश दिया। कृष्ण ने कहा, ''हे अर्जुन! तुम्हारा अधिकार केवल कर्म करने में है, उसके फल में नहीं।'' इसका मतलब यह नहीं है कि हमें फल की चिंता ही नहीं करनी चाहिए। इसका असली मतलब है कि जब हम फल से बहुत ज्यादा आसक्त हो जाते हैं, तो हम अपना वर्तमान कर्म बिगाड़ लेते हैं। यदि तुम सिर्फ इस बात पर ध्यान दोगे कि जीत मिलेगी या हार, तो तुम युद्ध लड़ ही नहीं पाओगे। इसलिए अपना सर्वश्रेष्ठ प्रदर्शन करो और परिणाम मुझ पर छोड़ दो। जीवन में भी यही सच है। हमारा नियंत्रण केवल हमारे प्रयासों पर होता है, नतीजों पर नहीं। यही निष्काम कर्म योग है, जो इंसान को हर चिंता और भय से मुक्त कर देता है।", "estimated_speech_sec": 70.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कर्मण्येवाधिकारस्ते का सच्चा अर्थ?", "image_prompt": "Lord Krishna and Arjuna on the chariot in Kurukshetra battlefield, glowing divine aura, epic Mahabharata scene, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "कुरुक्षेत्र के युद्ध में जब अर्जुन टूट गए...", "image_prompt": "Arjuna looking sad and dropping his Gandiva bow on the chariot, armies in the background, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "अपनों को सामने देखकर वह मोह में पड़ गए।", "image_prompt": "Arjuna looking across the battlefield at Bhishma and Drona, conflicted expression, cinematic fog, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "तब भगवान श्री कृष्ण ने उपदेश दिया।", "image_prompt": "Lord Krishna smiling calmly and speaking to Arjuna, cosmic light radiating from Krishna, masterpiece art, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "तुम्हारा अधिकार केवल कर्म करने में है...", "image_prompt": "Close up of Krishna''s hand in a teaching mudra, glowing golden energy, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "उसके फल में नहीं।", "image_prompt": "A beautiful blossoming lotus flower in muddy water, symbolizing detachment, soft lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "इसका मतलब फल की चिंता छोड़ना नहीं है।", "image_prompt": "A modern or ancient warrior focusing intensely on sharpening his sword, deep focus, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "बल्कि फल के मोह से मुक्त होना है।", "image_prompt": "A person walking on a glowing path of light towards a temple, peaceful atmosphere, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "जीत या हार के बारे में सोचोगे...", "image_prompt": "A balance scale weighing a golden crown and a sword, dramatic shadows, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "तो अपना वर्तमान कर्म बिगाड़ लोगे।", "image_prompt": "An archer missing the target because he is looking away, symbolic representation, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "सर्वश्रेष्ठ प्रदर्शन करो और परिणाम मुझ पर छोड़ दो।", "image_prompt": "Arjuna picking up his bow with renewed confidence, glowing eyes, ready to fight, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यही निष्काम कर्म योग है।", "image_prompt": "A serene meditating figure with the cosmos swirling around them, inner peace, spiritual, 9:16", "approx_sec": 4.0}]}' WHERE id = 'gita_karma_yoga';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "shiva_third_eye_kama", "title": "भगवान शिव का तीसरा नेत्र", "category": "शिव पुराण", "script_hi": "भगवान शिव का तीसरा नेत्र कब और क्यों खुला? सती की मृत्यु के बाद भगवान शिव गहरे ध्यान में चले गए थे। दूसरी ओर, तारकासुर नाम के असुर को वरदान था कि उसे सिर्फ शिव का पुत्र ही मार सकता है। देवताओं ने शिव जी का ध्यान तोड़ने के लिए कामदेव को भेजा। कामदेव ने अपने फूलों के बाण शिव जी पर चलाए, जिससे उनके मन में प्रेम की भावना जाग गई। लेकिन अपनी तपस्या भंग होने पर शिव जी को भयंकर क्रोध आया। उन्होंने तुरंत अपना तीसरा नेत्र खोला, और उससे निकली आग ने पल भर में कामदेव को जलाकर भस्म कर दिया। कामदेव की पत्नी रति के रोने पर शिव जी ने कहा कि कामदेव अब बिना शरीर के हर प्राणी के मन में वास करेंगे। यह कथा हमें सिखाती है कि जब इंसान की चेतना (तीसरा नेत्र) जागृत होती है, तो उसके भीतर की सभी वासनाएं (कामदेव) अपने आप भस्म हो जाती हैं।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "भगवान शिव का तीसरा नेत्र कब खुला?", "image_prompt": "Close up of Lord Shiva''s face with the third eye glowing bright orange, intense divine aura, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "सती की मृत्यु के बाद शिव ध्यान में थे।", "image_prompt": "Lord Shiva meditating deeply in the snowy peaks of Mount Kailash, peaceful and isolated, cinematic, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "इधर तारकासुर का आतंक बढ़ रहा था।", "image_prompt": "A giant terrifying demon Tarakasura roaring, dark and fiery background, mythological art, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "देवताओं ने कामदेव को भेजा।", "image_prompt": "Kamadeva, the Hindu god of love, holding a bow made of sugarcane and arrows of flowers, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "कामदेव ने शिव पर फूलों के बाण चलाए।", "image_prompt": "Kamadeva shooting glowing floral arrows towards meditating Lord Shiva, magical colorful dust, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "शिव जी की तपस्या भंग हो गई।", "image_prompt": "Lord Shiva opening his two eyes, looking slightly disturbed and angry, cold blue tones, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "उन्हें भयंकर क्रोध आया।", "image_prompt": "Shiva''s face turning furious, the cosmic third eye on his forehead starting to crack open and emit fire, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "और उन्होंने अपना तीसरा नेत्र खोल दिया!", "image_prompt": "A massive beam of fiery energy shooting out from Shiva''s third eye, epic dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "कामदेव पल भर में भस्म हो गए।", "image_prompt": "Kamadeva turning into a pile of grey ashes amidst blazing fire, tragic and powerful, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "रति के विलाप पर शिव ने वरदान दिया...", "image_prompt": "Goddess Rati weeping near the ashes, Lord Shiva looking at her with compassion, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "कि कामदेव अब बिना शरीर के वास करेंगे।", "image_prompt": "A glowing ethereal form of Kamadeva rising as pure energy, entering the hearts of beings, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "चेतना जागने पर वासनाएं भस्म हो जाती हैं।", "image_prompt": "A glowing third eye symbol radiating spiritual light, destroying dark shadows, spiritual awakening concept, 9:16", "approx_sec": 5.0}]}' WHERE id = 'shiva_third_eye_kama';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ramayana_hanuman_sun", "title": "जब हनुमान जी ने सूर्य को फल समझा", "category": "रामायण कथा", "script_hi": "जब हनुमान जी ने सूर्य को फल समझा। बचपन में एक दिन बाल हनुमान को बहुत ज़ोर की भूख लगी। उन्होंने आसमान में देखा तो उन्हें लाल चमकता हुआ सूर्य दिखाई दिया। हनुमान जी को लगा कि वह कोई बहुत बड़ा और मीठा फल है। वे बिना कुछ सोचे-समझे उड़कर आसमान में चले गए और सूर्य देव को अपने मुंह में रख लिया। पूरे ब्रह्मांड में अंधेरा छा गया। यह देखकर देवराज इंद्र घबरा गए और उन्होंने अपने वज्र से हनुमान जी की ठोड़ी (हनु) पर प्रहार किया। प्रहार से हनुमान जी बेहोश होकर धरती पर गिर पड़े। जब पवन देव ने यह देखा, तो उन्होंने क्रोधित होकर पूरे संसार की हवा रोक दी। तब सभी देवताओं ने आकर पवन देव से क्षमा मांगी और बाल हनुमान को अनेक दिव्य वरदान दिए। इसी वज्र के प्रहार के कारण उनका नाम ''हनुमान'' पड़ा।", "estimated_speech_sec": 70.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "जब हनुमान जी ने सूर्य को फल समझा।", "image_prompt": "Cute baby Hanuman looking up at the glowing red sun in the sky with hungry eyes, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "बाल हनुमान को बहुत भूख लगी थी।", "image_prompt": "Baby Hanuman holding his stomach, sitting on a mountain peak, ancient India setting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "वे उड़कर आसमान में चले गए...", "image_prompt": "Baby Hanuman flying upwards towards the giant blazing sun, dynamic comic style mythology, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "और सूर्य को अपने मुंह में रख लिया।", "image_prompt": "Baby Hanuman with puffed cheeks having swallowed the glowing sun, the sky turning dark, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "पूरे ब्रह्मांड में अंधेरा छा गया।", "image_prompt": "The entire cosmos in pitch darkness, stars visible, panicked gods in the background, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "इंद्र देव घबरा गए।", "image_prompt": "Lord Indra riding his white elephant Airavata, looking panicked and holding the lightning Vajra, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "उन्होंने अपने वज्र से प्रहार किया।", "image_prompt": "Indra throwing a glowing lightning bolt (Vajra) towards baby Hanuman in the sky, dramatic lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "हनुमान जी धरती पर गिर पड़े।", "image_prompt": "Baby Hanuman falling unconscious towards the earth, glowing aura fading, sad mythological scene, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "पवन देव क्रोधित हो गए।", "image_prompt": "Vayu (Wind God) holding unconscious baby Hanuman in his arms, looking extremely furious, storm brewing, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "संसार की हवा रुक गई।", "image_prompt": "Nature suffocating, trees completely still, beings gasping for air, atmospheric tension, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "देवताओं ने क्षमा मांगी और वरदान दिए।", "image_prompt": "Brahma, Shiva, and other gods blessing baby Hanuman with glowing divine light, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "इसी प्रहार से नाम पड़ा ''हनुमान''!", "image_prompt": "A majestic portrait of Lord Hanuman with a glowing aura, representing his immense strength and devotion, 9:16", "approx_sec": 5.0}]}' WHERE id = 'ramayana_hanuman_sun';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "jyotish_sade_sati_shani", "title": "शनिदेव की साढ़े साती का सच", "category": "नक्षत्र एवं ग्रह ज्ञान", "script_hi": "शनिदेव की साढ़े साती का असली सच क्या है? लोग साढ़े साती का नाम सुनते ही कांपने लगते हैं। ऐसा लगता है जैसे यह कोई बहुत बड़ा श्राप हो। लेकिन वैदिक ज्योतिष के अनुसार, शनि देव कोई क्रूर ग्रह नहीं हैं, बल्कि वे हमारे कर्मों के न्यायाधीश (Judge) हैं। साढ़े साती वह सात-साढ़े सात साल का समय होता है, जब शनि देव आपकी कुंडली के चंद्रमा के ऊपर से गुजरते हैं। इस दौरान वे आपके जीवन से सभी झूठे रिश्तों, अहंकार और गलत आदतों को निचोड़ कर बाहर निकाल देते हैं। जो लोग ईमानदार और मेहनती हैं, उन्हें साढ़े साती में रंक से राजा बनते हुए भी देखा गया है। शनिदेव बस यह चाहते हैं कि आप सोने की तरह तप कर निखरें। इसलिए साढ़े साती से डरने के बजाय, अपने कर्मों को शुद्ध रखें। शनिदेव दंड नहीं, बल्कि न्याय देते हैं।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "शनिदेव की साढ़े साती का असली सच?", "image_prompt": "Lord Shani Dev sitting on his crow chariot, holding a staff, dark cosmic blue and black aura, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "लोग इसका नाम सुनते ही डर जाते हैं।", "image_prompt": "A silhouette of a person looking terrified at a giant glowing ring of Saturn in the sky, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "मानो यह कोई बहुत बड़ा श्राप हो।", "image_prompt": "Dark storm clouds gathering over a lonely house, lightning strikes, eerie atmosphere, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "लेकिन शनि देव क्रूर नहीं हैं...", "image_prompt": "A glowing majestic face of Lord Shani with eyes of deep wisdom and justice, not anger, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "वे हमारे कर्मों के न्यायाधीश हैं।", "image_prompt": "A massive glowing scale of justice balancing karma, cosmic background, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "साढ़े साती वह समय है जब...", "image_prompt": "A glowing clock transitioning through 7.5 years, astronomical elements, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "शनि आपकी कुंडली के चंद्रमा से गुजरते हैं।", "image_prompt": "The dark planet Saturn slowly eclipsing the glowing Moon in space, astrology chart lines overlay, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "वे झूठे रिश्तों और अहंकार को तोड़ते हैं।", "image_prompt": "A glass mirror shattering, revealing a pure golden light behind it, symbolic art, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "ईमानदार लोगों को रंक से राजा बनाते हैं।", "image_prompt": "A poor man working hard, transitioning into a successful king-like figure wearing a crown, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "वे चाहते हैं कि आप सोने की तरह तपें।", "image_prompt": "Liquid gold being purified in a glowing crucible, intense fire, highly detailed, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "इसलिए साढ़े साती से डरें नहीं।", "image_prompt": "A person meditating calmly in the middle of a heavy storm, protected by a blue aura, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "शनिदेव दंड नहीं, न्याय देते हैं।", "image_prompt": "Lord Shani raising his hand in blessing (Abhaya Mudra), radiating protective and just energy, 9:16", "approx_sec": 6.0}]}' WHERE id = 'jyotish_sade_sati_shani';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "mahabharata_karna_kavach", "title": "कर्ण के कवच कुंडल का दान", "category": "महाभारत रहस्य", "script_hi": "दानवीर कर्ण के कवच और कुंडल का रहस्य क्या है? सूर्यपुत्र कर्ण जब जन्म लिए थे, तो उनके शरीर पर जन्म से ही अभेद्य कवच और कुंडल थे। जब तक ये उनके शरीर पर थे, दुनिया का कोई भी अस्त्र-शस्त्र उन्हें मार नहीं सकता था। कुरुक्षेत्र के युद्ध से पहले, देवराज इंद्र को अपने पुत्र अर्जुन की चिंता सताने लगी। वे जानते थे कि कर्ण को हराना असंभव है। इसलिए इंद्र ने एक गरीब ब्राह्मण का भेष बनाया और कर्ण के पास दान मांगने पहुंच गए। कर्ण, जो हर सुबह सूर्य पूजा के बाद किसी को भी खाली हाथ नहीं लौटाते थे, तुरंत समझ गए कि यह कोई साधारण ब्राह्मण नहीं, बल्कि स्वयं इंद्र हैं। इसके बावजूद, कर्ण ने बिना एक पल की हिचकिचाहट के अपने शरीर से चिपके हुए कवच और कुंडल को अपने ही हाथों से काट कर निकाल दिया और इंद्र को दान में दे दिया। उनका यह निस्वार्थ त्याग और वचनबद्धता ही उन्हें महाभारत का सबसे महान दानवीर बनाती है, जिसे इतिहास आज भी सम्मान से याद करता है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कर्ण के कवच कुंडल का रहस्य?", "image_prompt": "A majestic portrait of Karna with glowing golden armor (Kavach) and earrings (Kundal) naturally attached to his body, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "जब तक ये उनके शरीर पर थे...", "image_prompt": "Karna standing invincible on a battlefield, arrows deflecting off his glowing golden chest armor, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "कोई भी अस्त्र उन्हें मार नहीं सकता था।", "image_prompt": "A glowing magical shield surrounding Karna, divine lighting, ancient Indian warrior style, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "इंद्र को अपने पुत्र अर्जुन की चिंता सताने लगी।", "image_prompt": "Lord Indra looking worried while watching Arjuna practice archery from the heavens, celestial clouds, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "इंद्र ने एक गरीब ब्राह्मण का भेष बनाया।", "image_prompt": "Lord Indra disguised as an old, frail Brahmin holding a walking stick, entering a royal camp, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "और कर्ण के पास दान मांगने पहुंच गए।", "image_prompt": "The disguised Brahmin standing before Karna, who has just finished his morning sun worship by the river, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "कर्ण तुरंत समझ गए कि यह इंद्र हैं।", "image_prompt": "Karna looking deeply into the eyes of the old Brahmin, realizing his true divine identity, intense gaze, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "इसके बावजूद, कर्ण पीछे नहीं हटे।", "image_prompt": "Karna taking out a sharp dagger with a determined and calm expression on his face, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "उन्होंने बिना हिचकिचाहट के अपना कवच काट दिया।", "image_prompt": "Karna painfully peeling off the glowing golden armor from his own chest, blood dripping slightly, dramatic, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "और इंद्र को दान में दे दिया।", "image_prompt": "Karna handing over the glowing armor and earrings to the shocked Brahmin, ultimate sacrifice, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "इंद्र इस त्याग को देखकर लज्जित हो गए।", "image_prompt": "The Brahmin revealing his true form as Lord Indra, looking down in shame and awe at Karna, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यही कारण है कि वे सबसे महान दानवीर कहलाए।", "image_prompt": "A glorious silhouette of Karna with the sun rising behind him, representing eternal glory, 9:16", "approx_sec": 4.0}]}' WHERE id = 'mahabharata_karna_kavach';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "jyotish_jupiter_gurus", "title": "गुरु ग्रह और ज्ञान का रहस्य", "category": "नक्षत्र एवं ग्रह ज्ञान", "script_hi": "वैदिक ज्योतिष में गुरु यानी बृहस्पति ग्रह को इतना शुभ क्यों माना जाता है? नवग्रहों में देवगुरु बृहस्पति ज्ञान, भाग्य, धर्म और विस्तार के कारक हैं। जिस व्यक्ति की कुंडली में गुरु मजबूत होता है, वह इंसान चाहे कितनी भी बड़ी मुसीबत में क्यों न फँस जाए, कोई न कोई अदृश्य शक्ति उसे बचा ही लेती है। गुरु वह प्रकाश है जो अज्ञान के अंधेरे को दूर करता है। अगर राहु भ्रम है, तो गुरु उस भ्रम को तोड़ने वाला सच है। एक मजबूत गुरु आपको सिर्फ धन ही नहीं, बल्कि सम्मान, नैतिकता और आंतरिक शांति भी देता है। भगवान राम की कुंडली में भी गुरु लग्न में विराजमान थे, जिसने उन्हें हर विपत्ति में सही रास्ता दिखाया और मर्यादा पुरुषोत्तम बनाया। इसलिए, जब आपके जीवन में गुरु ग्रह की दशा आती है, तो यह आपको अध्यात्म, सच्चे गुरुओं का सान्निध्य और जीवन का असली उद्देश्य प्रदान करती है। गुरु कृपा के बिना जीवन में कोई भी बड़ी सफलता प्राप्त करना असंभव है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "गुरु ग्रह को इतना शुभ क्यों माना जाता है?", "image_prompt": "A glowing majestic yellow planet Jupiter (Brihaspati) in the cosmos, radiating golden divine light, astrology art, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "बृहस्पति ज्ञान, भाग्य और धर्म के कारक हैं।", "image_prompt": "An ancient sage teaching a group of students under a banyan tree, peaceful golden hour lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "जिसकी कुंडली में गुरु मजबूत होता है...", "image_prompt": "A glowing golden aura protecting a person standing calmly in the middle of chaos, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "उसे अदृश्य शक्ति बचा ही लेती है।", "image_prompt": "A divine golden hand coming down from the heavens to shield a person from a falling rock, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "गुरु वह प्रकाश है जो अज्ञान को दूर करता है।", "image_prompt": "A massive glowing candle illuminating a pitch black room, symbolic representation of wisdom, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "अगर राहु भ्रम है, तो गुरु सच है।", "image_prompt": "A bright golden light cutting through thick, dark, smoky illusions, cosmic battle of energies, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "यह सिर्फ धन नहीं, सम्मान भी देता है।", "image_prompt": "A respected king or scholar being bowed to by the public, representing honor and ethics, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "भगवान राम की कुंडली में भी गुरु लग्न में थे।", "image_prompt": "Lord Rama standing tall with his bow, a subtle glowing yellow aura (Jupiter) surrounding his form, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "जिसने उन्हें हर विपत्ति में सही रास्ता दिखाया।", "image_prompt": "A glowing compass pointing towards the light in a dark forest, symbolic of divine guidance, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "गुरु ग्रह की दशा आपको अध्यात्म की ओर ले जाती है।", "image_prompt": "A person meditating deeply, floating slightly with a glowing golden third eye and crown chakra, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "सच्चे गुरुओं का सान्निध्य प्राप्त होता है।", "image_prompt": "A seeker touching the feet of a glowing divine guru, receiving blessings and knowledge, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "गुरु कृपा के बिना बड़ी सफलता असंभव है।", "image_prompt": "A grand golden lotus blooming in the cosmos, representing ultimate success and divine grace, 9:16", "approx_sec": 4.0}]}' WHERE id = 'jyotish_jupiter_gurus';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "gita_vishvarupa", "title": "श्री कृष्ण का विश्वरूप दर्शन", "category": "श्रीमद्भगवद्गीता", "script_hi": "महाभारत के युद्ध में जब श्री कृष्ण ने अपना विश्वरूप दिखाया तो क्या हुआ? गीता के ग्यारहवें अध्याय में, जब अर्जुन ने भगवान से उनके असली ब्रह्मांडीय रूप को देखने की विनती की, तो कृष्ण ने मुस्कुराते हुए कहा कि तुम इन साधारण आँखों से मुझे नहीं देख सकते। इसलिए, कृष्ण ने अर्जुन को ''दिव्य दृष्टि'' प्रदान की। जैसे ही अर्जुन ने आँखें खोलीं, उन्होंने देखा कि कृष्ण के शरीर में हजारों सूर्य एक साथ चमक रहे हैं। उनके अनगिनत मुख, अनगिनत हाथ और आँखें थीं। उस रूप में संपूर्ण ब्रह्मांड, सभी देवता, ग्रह, तारे, भूत, भविष्य और वर्तमान एक ही पल में दिखाई दे रहे थे। अर्जुन ने देखा कि कौरवों की पूरी सेना, भीष्म और द्रोण सब भगवान के मुख रूपी काल में समा रहे हैं। इस भयंकर और विशाल रूप को देखकर अर्जुन कांप उठे और उन्होंने हाथ जोड़कर कृष्ण से विनती की कि वे अपने सौम्य रूप में वापस आ जाएं। यह दर्शन हमें बताता है कि यह संपूर्ण सृष्टि ईश्वर का ही विस्तार है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "जब श्री कृष्ण ने अपना विश्वरूप दिखाया...", "image_prompt": "Lord Krishna transforming on the Kurukshetra battlefield, glowing light expanding from his body, epic scale, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "अर्जुन ने असली रूप देखने की विनती की।", "image_prompt": "Arjuna kneeling with folded hands in front of Krishna on the chariot, pleading respectfully, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "साधारण आँखों से यह रूप नहीं देखा जा सकता।", "image_prompt": "Krishna touching Arjuna''s forehead with a glowing finger, granting him divine vision (Divya Drishti), 9:16", "approx_sec": 6.0}, {"slide_index": 4, "caption": "कृष्ण के शरीर में हजारों सूर्य चमक रहे थे।", "image_prompt": "A blinding golden light radiating like a thousand suns, abstract divine energy, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "अनगिनत मुख, अनगिनत हाथ और आँखें...", "image_prompt": "The cosmic Vishvarupa of Krishna, featuring thousands of heads and arms holding various weapons, cosmic scale, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "संपूर्ण ब्रह्मांड उनके भीतर था।", "image_prompt": "Galaxies, stars, and planets swirling inside the colossal glowing body of Lord Krishna, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "भूत, भविष्य और वर्तमान एक ही पल में।", "image_prompt": "A surreal visual of time flowing like a glowing river inside the cosmic form of God, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "कौरवों की सेना उनके मुख में समा रही थी।", "image_prompt": "Warriors of the Kaurava army, including chariots, being pulled into the fiery, terrifying mouth of Time (Kaal), 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "यह देखकर अर्जुन कांप उठे।", "image_prompt": "Arjuna trembling with fear and awe, shielding his eyes from the overwhelming blinding light, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "उन्होंने कृष्ण से सौम्य रूप में आने की विनती की।", "image_prompt": "Arjuna bowing completely to the ground in surrender, praying for the terrifying vision to stop, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "कृष्ण वापस अपने मुस्कुराते हुए रूप में आ गए।", "image_prompt": "Lord Krishna back in his beautiful two-armed form, smiling kindly at Arjuna, soft warm light, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "संपूर्ण सृष्टि ईश्वर का ही विस्तार है।", "image_prompt": "A beautiful cosmic lotus flower dissolving into the shape of the universe, spiritual peace, 9:16", "approx_sec": 4.0}]}' WHERE id = 'gita_vishvarupa';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "shiva_neelkanth_origin", "title": "भगवान शिव ने विष क्यों पिया?", "category": "शिव पुराण", "script_hi": "भगवान शिव को नीलकंठ क्यों कहा जाता है? जब देवताओं और असुरों ने मिलकर क्षीरसागर (समुद्र) का मंथन किया, तो उसमें से चौदह अनमोल रत्न निकले। लेकिन अमृत से पहले, समुद्र से ''हलाहल'' नाम का एक बेहद भयंकर और जानलेवा विष निकला। उस विष की गर्मी इतनी भयानक थी कि उससे पूरा ब्रह्मांड जलने लगा। देवता, असुर और मनुष्य, सब प्राण बचाने के लिए भगवान शिव की शरण में कैलाश पहुंचे। सृष्टि की रक्षा के लिए, महादेव ने उस भयंकर विष को अपनी अंजुली में लिया और पी गए। लेकिन अगर वह विष उनके पेट में जाता, तो उनके हृदय में बसने वाले भगवान राम को कष्ट होता। इसलिए माता पार्वती ने तुरंत शिव जी का गला पकड़ लिया, और विष उनके गले में ही रुक गया। उस भयानक विष के प्रभाव से भगवान शिव का कंठ (गला) पूरी तरह से नीला पड़ गया। उसी दिन से महादेव को ''नीलकंठ'' के नाम से जाना जाने लगा। यह कथा हमें सिखाती है कि महान वही है जो दूसरों की भलाई के लिए बुराई का विष स्वयं पी ले।", "estimated_speech_sec": 80.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "भगवान शिव को नीलकंठ क्यों कहा जाता है?", "image_prompt": "Close up of Lord Shiva''s majestic face with a glowing blue throat, serene expression, snowy background, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "जब समुद्र का मंथन हुआ...", "image_prompt": "Gods and Demons pulling the giant serpent Vasuki to churn the cosmic ocean around Mount Mandara, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उसमें से चौदह अनमोल रत्न निकले।", "image_prompt": "Glowing magical artifacts like a divine horse, elephant, and gems emerging from the churning ocean, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "लेकिन अमृत से पहले हलाहल विष निकला।", "image_prompt": "A bubbling cauldron of dark, green toxic smoke emerging from the ocean, melting everything nearby, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "उस विष से पूरा ब्रह्मांड जलने लगा।", "image_prompt": "The toxic green smoke spreading across the cosmos, stars fading, beings coughing and collapsing, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "सभी देवता शिव जी की शरण में कैलाश पहुंचे।", "image_prompt": "Gods like Indra and Brahma folding hands in front of Lord Shiva who is meditating on a tiger skin, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "महादेव ने विष को अपनी अंजुली में लिया...", "image_prompt": "Lord Shiva holding the dark, glowing, toxic poison in his cupped hands, completely fearless, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "और उसे पी गए! ", "image_prompt": "Lord Shiva swallowing the glowing green poison, intense dramatic lighting from below, epic, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "माता पार्वती ने तुरंत उनका गला पकड़ लिया।", "image_prompt": "Goddess Parvati rushing and placing her gentle hands firmly on Shiva''s throat to stop the poison, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "विष गले में ही रुक गया।", "image_prompt": "The toxic energy concentrating and glowing brightly right at Shiva''s throat, turning it deep blue, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "उसी दिन से वे ''नीलकंठ'' कहलाए।", "image_prompt": "A divine portrait of Shiva with a beautiful blue throat, radiating peace and cosmic balance, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "महान वही है जो दूसरों के लिए विष पी ले।", "image_prompt": "A symbolic image of a glowing blue lotus growing out of dark toxic mud, signifying sacrifice and purity, 9:16", "approx_sec": 5.0}]}' WHERE id = 'shiva_neelkanth_origin';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "jyotish_mars_manglik", "title": "मंगल दोष का सच्चा रहस्य", "category": "ज्योतिष कथा", "script_hi": "मंगल दोष (मांगलिक) का नाम सुनते ही लोग शादियों से क्यों डरने लगते हैं? वैदिक ज्योतिष में मंगल ग्रह को अग्नि, युद्ध, और ऊर्जा का सेनापति कहा गया है। जब मंगल जन्म कुंडली के प्रथम, चतुर्थ, सप्तम, अष्टम या द्वादश भाव में बैठता है, तो उसे ''मंगल दोष'' कहा जाता है। लोग सोचते हैं कि मांगलिक होने का मतलब है कि शादी टूट जाएगी या जीवनसाथी को खतरा है। लेकिन यह एक बहुत बड़ा भ्रम है! मंगल दोष वास्तव में आपके अंदर मौजूद अत्यधिक ऊर्जा (Energy) और आक्रामकता को दर्शाता है। एक मांगलिक व्यक्ति बहुत तेज़, महत्वाकांक्षी और उग्र स्वभाव का होता है। यदि उसकी शादी किसी शांत (Non-Manglik) व्यक्ति से हो जाए, तो उनकी ऊर्जा आपस में टकराती है और झगड़े होते हैं। इसलिए मांगलिक की शादी मांगलिक से की जाती है, ताकि दोनों की ''फायर एनर्जी'' बराबर रहे और एक-दूसरे को समझ सकें। मंगल दोष कोई श्राप नहीं है, बल्कि यह वह ऊर्जा है जो आपको जीवन में बड़े लक्ष्य हासिल करने की शक्ति देती है। बस इसे सही दिशा देने की जरूरत है!", "estimated_speech_sec": 80.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "मंगल दोष का नाम सुनते ही डर क्यों?", "image_prompt": "A glowing red Mars planet with an aggressive fiery aura, casting a shadow over a wedding mandap, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "मंगल ग्रह ऊर्जा और युद्ध का सेनापति है।", "image_prompt": "Lord Mangala (Mars) as a fierce red warrior god holding a spear, riding a ram, intense energy, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "जब मंगल खास भावों में बैठता है...", "image_prompt": "An astrology Kundali chart with a glowing red ''Mangal'' (Mars) in the 7th house (marriage house), 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "तो उसे ''मंगल दोष'' कहा जाता है।", "image_prompt": "A magnifying glass focusing on the red planet in the chart, warning signs or glowing red light, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "लोग सोचते हैं इससे जीवनसाथी को खतरा है।", "image_prompt": "A silhouette of a worried couple standing apart, a crack forming in the ground between them, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "लेकिन यह एक बहुत बड़ा भ्रम है!", "image_prompt": "A bright light shattering the crack, revealing a strong glowing chain linking two hands together, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "मंगल दोष आपके अंदर अत्यधिक ऊर्जा को दर्शाता है।", "image_prompt": "A person meditating with a powerful red fiery aura bursting from their core, symbolizing immense inner energy, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "मांगलिक व्यक्ति बहुत तेज़ और महत्वाकांक्षी होता है।", "image_prompt": "A modern successful person standing confidently on a mountain peak, red sky background, victorious, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "शांत व्यक्ति से शादी होने पर ऊर्जा टकराती है।", "image_prompt": "A raging fire on one side and calm water on the other side clashing and creating steam and chaos, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "इसलिए मांगलिक की शादी मांगलिक से की जाती है।", "image_prompt": "Two bright, matching bonfires burning together harmoniously in a dark forest, beautiful and balanced, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "ताकि दोनों की ''फायर एनर्जी'' बराबर रहे।", "image_prompt": "A glowing red string of fate strongly connecting a happy couple, radiating warmth and strength, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "यह कोई श्राप नहीं, आपकी ताकत है!", "image_prompt": "A fierce red lion standing proudly, symbolizing strength, courage, and pure unbridled energy, 9:16", "approx_sec": 5.0}]}' WHERE id = 'jyotish_mars_manglik';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "mahabharata_abhimanyu_chakravyuh", "title": "अभिमन्यु और चक्रव्यूह का ज्ञान", "category": "महाभारत रहस्य", "script_hi": "महाभारत के सबसे युवा योद्धा अभिमन्यु ने चक्रव्यूह का रहस्य कैसे जाना? जब अभिमन्यु अपनी माता सुभद्रा के गर्भ में थे, तब एक रात अर्जुन ने सुभद्रा को चक्रव्यूह भेदने की युद्ध नीति सुनानी शुरू की। अर्जुन ने विस्तार से बताया कि चक्रव्यूह के छह द्वारों को कैसे तोड़ा जाता है। गर्भ में पल रहा शिशु अभिमन्यु यह सब सुन रहा था। लेकिन जैसे ही अर्जुन सातवें और अंतिम द्वार से बाहर निकलने की तकनीक बताने लगे, सुभद्रा को नींद आ गई। चूँकि माता सो गई थीं, इसलिए शिशु अभिमन्यु अंतिम द्वार का रहस्य नहीं सुन सका। वर्षों बाद, कुरुक्षेत्र के युद्ध में जब द्रोणाचार्य ने चक्रव्यूह की रचना की और अर्जुन वहाँ नहीं थे, तब 16 वर्षीय अभिमन्यु ने अकेले ही चक्रव्यूह में प्रवेश किया। उसने वीरता से छह द्वार तोड़ दिए, लेकिन बाहर निकलने का ज्ञान न होने के कारण कौरवों ने कायरता से उसे घेर लिया और मार डाला। यह कहानी सिखाती है कि गर्भ में पल रहा बच्चा भी बाहरी दुनिया के ज्ञान को ग्रहण करता है।", "estimated_speech_sec": 75.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "अभिमन्यु ने चक्रव्यूह का रहस्य कैसे जाना?", "image_prompt": "A glorious and brave 16-year-old warrior Abhimanyu holding his bow, standing alone on a battlefield, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "जब अभिमन्यु सुभद्रा के गर्भ में थे...", "image_prompt": "Pregnant Goddess Subhadra resting peacefully, glowing divine aura around her womb, ancient Indian bedroom, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "अर्जुन ने उन्हें चक्रव्यूह भेदने की नीति सुनाई।", "image_prompt": "Arjuna sitting beside pregnant Subhadra, enthusiastically explaining military strategy using hand gestures, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "गर्भ में पल रहा शिशु सब सुन रहा था।", "image_prompt": "A mystical glowing visualization of a baby inside the womb absorbing golden knowledge floating from outside, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "अर्जुन ने छह द्वार तोड़ने का रहस्य बताया।", "image_prompt": "A top-down view of a complex, glowing, spinning military formation (Chakravyuh) made of soldiers, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "लेकिन जब बाहर निकलने की बारी आई...", "image_prompt": "Arjuna leaning in to tell the final secret, dramatic candlelight casting shadows, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "सुभद्रा को नींद आ गई।", "image_prompt": "Subhadra deeply asleep, breathing peacefully, missing the rest of the conversation, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "कुरुक्षेत्र के युद्ध में जब अर्जुन नहीं थे...", "image_prompt": "Dronacharya confidently commanding the massive Kaurava army to form the deadly Chakravyuh formation, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "16 वर्षीय अभिमन्यु ने अकेले प्रवेश किया।", "image_prompt": "Young Abhimanyu fearlessly charging alone towards the massive spinning wall of enemy soldiers, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "उसने वीरता से छह द्वार तोड़ दिए।", "image_prompt": "Abhimanyu fighting fiercely, arrows flying everywhere, destroying chariots, heroic battle scene, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "लेकिन बाहर निकलने का ज्ञान न होने के कारण...", "image_prompt": "Abhimanyu surrounded by seven great Kaurava warriors attacking him simultaneously from all sides, tragic, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "गर्भ का ज्ञान भी असर डालता है।", "image_prompt": "A beautiful golden lotus blooming out of a broken chariot wheel, signifying his eternal glory, 9:16", "approx_sec": 4.0}]}' WHERE id = 'mahabharata_abhimanyu_chakravyuh';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "shiva_parvati_vivah", "title": "शिव और पार्वती का अद्भुत विवाह", "category": "शिव पुराण", "script_hi": "भगवान शिव की बारात दुनिया की सबसे अनोखी बारात क्यों थी? जब माता पार्वती ने शिव जी को पति रूप में पाने के लिए कठोर तपस्या की, तो शिव जी ने उनका प्रस्ताव स्वीकार कर लिया। विवाह के दिन, जब राजा हिमाचल के महल में शिव जी की बारात आई, तो सभी लोग डर के मारे कांप उठे। क्योंकि शिव जी किसी सजे हुए रथ पर नहीं, बल्कि एक बैल (नंदी) पर सवार थे। उनके शरीर पर भस्म लगी थी, गले में सांप लिपटे थे, और उनकी बारात में देवी-देवताओं के साथ-साथ भूत, प्रेत, पिशाच, चुड़ैलें और भयंकर दिखने वाले गण नाच रहे थे। पार्वती की माता मैनावती यह भयानक दृश्य देखकर बेहोश हो गईं। उन्होंने कहा कि मैं अपनी बेटी का विवाह ऐसे वैरागी से नहीं करूंगी! तब पार्वती जी ने शिव जी से प्रार्थना की कि वे अपने असली दिव्य रूप में आएं। शिव जी ने उनकी बात मानकर अपना सबसे सुंदर और चंद्र-समान रूप ''चंद्रशेखर'' धारण किया। उनका यह मनमोहक रूप देखकर सभी देवी-देवता और इंसान मंत्रमुग्ध हो गए, और फिर बड़े हर्षोल्लास के साथ उनका विवाह संपन्न हुआ।", "estimated_speech_sec": 85.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "शिव जी की बारात सबसे अनोखी क्यों थी?", "image_prompt": "Lord Shiva covered in ash, wearing leopard skin, sitting on Nandi the bull, leading a wild procession, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "पार्वती जी ने कठोर तपस्या की थी।", "image_prompt": "Goddess Parvati meditating deeply in a freezing snow-covered forest, glowing with inner spiritual heat, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "विवाह के दिन जब बारात महल पहुंची...", "image_prompt": "A beautiful ancient Indian palace decorated with flowers and lights for a grand royal wedding, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "सभी लोग डर के मारे कांप उठे!", "image_prompt": "Royal guests and queens looking absolutely terrified and running away in panic, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "बारात में भूत, प्रेत और पिशाच नाच रहे थे।", "image_prompt": "Creepy, weird-looking ghosts, goblins, and dancing skeletons celebrating wildly in the wedding procession, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "शिव जी के शरीर पर भस्म और सांप थे।", "image_prompt": "Close up of Lord Shiva looking wildly calm, snakes wrapped around his neck, ash on his skin, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "पार्वती की माता यह देखकर बेहोश हो गईं।", "image_prompt": "Queen Mainavati fainting into the arms of her maids after seeing the terrifying bridegroom, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "उन्होंने कहा, ''मैं अपनी बेटी का विवाह नहीं करूंगी!''", "image_prompt": "The furious queen pointing her finger towards the palace doors, crying and refusing the marriage, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "तब पार्वती जी ने शिव जी से प्रार्थना की...", "image_prompt": "Goddess Parvati dressed as a beautiful bride, praying with folded hands to Lord Shiva in her mind, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "शिव जी ने ''चंद्रशेखर'' रूप धारण किया।", "image_prompt": "Lord Shiva transforming into the most incredibly handsome cosmic prince, glowing with divine white light, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "सभी लोग उनका रूप देखकर मंत्रमुग्ध हो गए।", "image_prompt": "The crowd of royals and gods looking in complete awe and devotion at the beautiful Lord Shiva, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "और विवाह बड़े हर्षोल्लास से संपन्न हुआ।", "image_prompt": "Lord Shiva and Goddess Parvati taking the wedding vows around the holy fire, raining flower petals, 9:16", "approx_sec": 5.0}]}' WHERE id = 'shiva_parvati_vivah';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ganesha_head", "title": "गणेश जी को हाथी का सिर कैसे मिला?", "category": "शिव पुराण", "script_hi": "भगवान गणेश को हाथी का सिर कैसे मिला? एक बार माता पार्वती कैलाश पर्वत पर स्नान करने जा रही थीं। द्वार पर पहरा देने के लिए कोई नहीं था, इसलिए उन्होंने अपने शरीर के उबटन (हल्दी) से एक सुंदर बालक की मूर्ति बनाई और उसमें प्राण डाल दिए। यह बालक गणेश थे। माता ने उन्हें आदेश दिया कि जब तक वे स्नान कर रही हैं, कोई भी अंदर न आ पाए। थोड़ी देर बाद भगवान शिव वहां पहुंचे। बालक गणेश शिव को नहीं पहचानते थे, इसलिए उन्होंने महादेव को अंदर जाने से रोक दिया। शिव जी को बहुत क्रोध आया। उनके गणों ने बालक से युद्ध किया, लेकिन गणेश ने सबको हरा दिया। अंततः क्रोध में आकर शिव जी ने अपने त्रिशूल से गणेश का सिर धड़ से अलग कर दिया। जब पार्वती जी बाहर आईं और अपने पुत्र को मृत देखा, तो वे क्रोध से पूरी सृष्टि को नष्ट करने लगीं। उन्हें शांत करने के लिए, शिव जी ने भगवान विष्णु को उत्तर दिशा में भेजा। विष्णु जी एक ऐसे हाथी का सिर ले आए जो उत्तर की ओर सिर करके सो रहा था। शिव जी ने वह सिर बालक के धड़ पर लगा दिया और उन्हें पुनर्जीवित कर दिया। तभी से वे ''गजानन'' कहलाए।", "estimated_speech_sec": 85.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "गणेश जी को हाथी का सिर कैसे मिला?", "image_prompt": "A cute and divine boy made of glowing golden turmeric clay, opening his eyes for the first time, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "माता पार्वती ने उबटन से बालक बनाया।", "image_prompt": "Goddess Parvati lovingly touching the cheek of the newly created boy, ancient Indian cave setting, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "और उसे पहरा देने का आदेश दिया।", "image_prompt": "The boy holding a wooden staff, standing bravely guard outside a large beautifully carved wooden door, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "तभी वहां भगवान शिव आ गए।", "image_prompt": "Lord Shiva arriving at the door holding his Trishul, glowing with divine authority, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "गणेश ने उन्हें अंदर जाने से रोक दिया।", "image_prompt": "The little boy boldly blocking the path of the giant Lord Shiva with his staff, confident expression, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "शिव जी को बहुत क्रोध आया।", "image_prompt": "Lord Shiva looking furious, his eyes burning with anger, dark clouds gathering above, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "उन्होंने त्रिशूल से बालक का सिर काट दिया।", "image_prompt": "A glowing Trishul flying through the air and slicing, dramatic silhouette lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "पार्वती जी क्रोध से सृष्टि नष्ट करने लगीं!", "image_prompt": "Goddess Parvati transforming into a terrifying angry form, cosmic fire erupting around her, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "शिव जी ने तुरंत उपाय सोचा।", "image_prompt": "Lord Shiva looking deeply remorseful and commanding Lord Vishnu to find a solution, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "विष्णु जी एक हाथी का सिर लेकर आए।", "image_prompt": "Lord Vishnu holding the magnificent, glowing head of a divine elephant (Airavata species), 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "शिव जी ने सिर लगाकर उन्हें पुनर्जीवित किया।", "image_prompt": "Lord Shiva attaching the elephant head to the boy''s body, golden healing magic sealing it, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "और वे ''गजानन'' कहलाए!", "image_prompt": "Lord Ganesha in his complete elephant-headed form, smiling and holding a laddu, glowing aura, 9:16", "approx_sec": 5.0}]}' WHERE id = 'ganesha_head';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "kartikeya_peacock", "title": "कार्तिकेय और मोर की सवारी", "category": "शिव पुराण", "script_hi": "भगवान कार्तिकेय (मुरुगन) की सवारी मोर कैसे बना? तारकासुर का वध करने के बाद, उसके भाई शूरपद्मन (Surapadman) ने देवताओं पर हमला कर दिया। शूरपद्मन बहुत ही मायावी और शक्तिशाली असुर था। उसे वरदान था कि वह शिव की शक्ति के अलावा किसी भी चीज़ से नहीं मर सकता। इसलिए भगवान कार्तिकेय, जो शिव के तेज़ से उत्पन्न हुए थे, ने उससे युद्ध किया। युद्ध के दौरान, शूरपद्मन ने बचने के लिए एक विशाल आम के पेड़ का रूप धारण कर लिया। भगवान कार्तिकेय ने अपने दिव्य ''वेल'' (भाले) से उस पेड़ को दो हिस्सों में चीर दिया। पेड़ का एक हिस्सा एक सुंदर ''मोर'' बन गया और दूसरा हिस्सा एक ''मुर्गा'' बन गया। शूरपद्मन ने अपनी गलती मान ली और भगवान की शरण में आ गया। कार्तिकेय ने उसकी वीरता से प्रसन्न होकर मोर को अपना शाश्वत वाहन (सवारी) बना लिया और मुर्गे को अपने युद्ध के झंडे (ध्वज) पर स्थान दिया। इस तरह, भगवान कार्तिकेय ने अपने सबसे बड़े शत्रु को अपनी शरण देकर हमेशा के लिए अपने साथ जोड़ लिया।", "estimated_speech_sec": 80.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कार्तिकेय की सवारी मोर कैसे बना?", "image_prompt": "Lord Kartikeya (Murugan) looking fiercely handsome, sitting on a majestic glowing peacock, holding a spear, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "शूरपद्मन नाम के असुर ने हमला किया।", "image_prompt": "A terrifying demon Surapadman radiating dark energy, standing aggressively on a battlefield, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "वह बहुत मायावी और शक्तिशाली था।", "image_prompt": "The demon transforming his shape magically into shadows and beasts, dark magic aura, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "भगवान कार्तिकेय ने उससे युद्ध किया।", "image_prompt": "Lord Kartikeya holding his glowing golden Vel (spear), charging towards the demon, dynamic action, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "असुर ने एक विशाल आम के पेड़ का रूप ले लिया।", "image_prompt": "A massive, terrifying, dark magical mango tree with roots tearing up the ground, glowing red eyes in the bark, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "कार्तिकेय ने अपने दिव्य ''वेल'' से प्रहार किया।", "image_prompt": "Lord Kartikeya throwing the glowing golden Vel straight at the massive tree, sparks flying, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "और पेड़ को दो हिस्सों में चीर दिया।", "image_prompt": "The glowing spear splitting the massive tree perfectly down the middle, blinding light bursting out, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "एक हिस्सा सुंदर मोर बन गया...", "image_prompt": "One half of the tree magically transforming into a gigantic, beautiful blue and green peacock, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "और दूसरा हिस्सा एक मुर्गा बन गया।", "image_prompt": "The other half transforming into a bright, colorful, aggressive rooster, mythological style, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "असुर ने कार्तिकेय की शरण ली।", "image_prompt": "The peacock bowing its head in deep respect to Lord Kartikeya, admitting defeat and seeking grace, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "कार्तिकेय ने मोर को अपनी सवारी बना लिया।", "image_prompt": "Lord Kartikeya affectionately petting the giant peacock and sitting on its back, divine golden aura, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "और मुर्गे को अपने झंडे पर स्थान दिया।", "image_prompt": "A majestic war flag fluttering in the wind with the emblem of a glowing rooster on it, 9:16", "approx_sec": 4.0}]}' WHERE id = 'kartikeya_peacock';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ganga_descent", "title": "गंगा का धरती पर अवतरण", "category": "शिव पुराण", "script_hi": "गंगा नदी धरती पर कैसे आई? राजा भगीरथ के साठ हज़ार पूर्वज कपिल मुनि के श्राप से भस्म हो गए थे। उनकी मुक्ति के लिए भगीरथ ने कठोर तपस्या की ताकि पवित्र गंगा नदी स्वर्ग से धरती पर आ सके। माता गंगा धरती पर आने को तैयार हो गईं, लेकिन उनका वेग इतना प्रचंड था कि अगर वे सीधे धरती पर गिरतीं, तो पूरी पृथ्वी पाताल में बह जाती। इस विनाश को रोकने के लिए, भगीरथ ने भगवान शिव की तपस्या की। महादेव ने उनकी प्रार्थना सुनी और अपने बाल खोलकर हिमालय पर खड़े हो गए। जब गंगा स्वर्ग से भयंकर गर्जना के साथ नीचे गिरीं, तो शिव जी ने उन्हें अपनी जटाओं (बालों) में कैद कर लिया! गंगा कई दिनों तक शिव जी की जटाओं में भटकती रहीं। फिर, महादेव ने अपनी एक जटा खोली और गंगा को एक शांत नदी के रूप में धरती पर बहने दिया। इसी जल से भगीरथ के पूर्वजों को मोक्ष मिला। तभी से भगवान शिव को ''गंगाधर'' भी कहा जाता है।", "estimated_speech_sec": 80.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "गंगा नदी स्वर्ग से धरती पर कैसे आई?", "image_prompt": "A glowing heavenly river flowing through the cosmos among the stars in Swarga (Heaven), 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "राजा भगीरथ के पूर्वज भस्म हो गए थे।", "image_prompt": "Sixty thousand princes burning into ashes from the fiery gaze of Sage Kapila, ancient myth, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "भगीरथ ने गंगा को धरती पर लाने की तपस्या की।", "image_prompt": "King Bhagiratha standing on one leg in deep meditation, praying towards the heavens, snowy peaks, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "लेकिन गंगा का वेग बहुत प्रचंड था।", "image_prompt": "A terrifyingly massive waterfall of cosmic water threatening to crush the earth, apocalyptic feeling, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "धरती पाताल में बह जाती!", "image_prompt": "The globe of Earth cracking and sinking into deep dark cosmic waters, dramatic disaster concept, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "भगीरथ ने भगवान शिव से प्रार्थना की।", "image_prompt": "King Bhagiratha begging with folded hands in front of Lord Shiva''s massive meditating form, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "महादेव ने अपने बाल खोल दिए।", "image_prompt": "Lord Shiva standing tall on Mount Kailash, opening his massive, infinitely long matted hair (Jata), 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "गंगा भयंकर गर्जना के साथ नीचे गिरीं...", "image_prompt": "The powerful glowing river crashing down directly from the sky onto Shiva''s head, splashing wildly, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "और शिव जी की जटाओं में कैद हो गईं!", "image_prompt": "The massive river trapped and swirling endlessly inside the cosmic maze of Shiva''s matted hair, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "गंगा का अहंकार टूट गया।", "image_prompt": "Goddess Ganga looking humbled and calm, floating gently within the hair of Shiva, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "शिव जी ने एक जटा से उन्हें बाहर निकाला।", "image_prompt": "Lord Shiva pulling out one strand of hair, releasing a gentle, calm, sparkling stream of water, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "तभी से महादेव ''गंगाधर'' कहलाए।", "image_prompt": "A beautiful majestic portrait of Lord Shiva with the river Ganga sprouting from his hair, divine peace, 9:16", "approx_sec": 5.0}]}' WHERE id = 'ganga_descent';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "dadhichi_bones", "title": "महर्षि दधीचि का अस्थि दान", "category": "शिव पुराण", "script_hi": "महर्षि दधीचि का अस्थि दान क्यों ब्रह्मांड का सबसे बड़ा त्याग माना जाता है? एक बार वृत्रासुर नाम के एक भयंकर असुर ने स्वर्ग पर कब्ज़ा कर लिया। उसने ऐसा वरदान पाया था कि उसे दुनिया के किसी भी लकड़ी, पत्थर, या साधारण धातु के अस्त्र से नहीं मारा जा सकता था। इंद्र देव हताश होकर भगवान विष्णु के पास गए। विष्णु जी ने कहा कि वृत्रासुर को केवल एक ऐसे वज्र से मारा जा सकता है, जो किसी महान तपस्वी की हड्डियों से बना हो। सभी देवता महर्षि दधीचि के पास पहुँचे, जो अपनी घोर तपस्या के कारण अत्यंत पवित्र और शक्तिशाली हो चुके थे। जब इंद्र ने उनसे उनकी हड्डियाँ माँगी, तो दधीचि ने बिना एक पल की हिचकिचाहट के मुस्कुराते हुए अपना शरीर त्याग दिया। देवताओं ने उनकी रीढ़ की हड्डी से ''वज्र'' का निर्माण किया। इसी अजेय वज्र से इंद्र ने वृत्रासुर का वध किया और सृष्टि की रक्षा की। महर्षि दधीचि का यह बलिदान सिखाता है कि समाज और धर्म की रक्षा के लिए किया गया निःस्वार्थ त्याग ही सबसे महान है।", "estimated_speech_sec": 85.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "महर्षि दधीचि का अस्थि दान सबसे बड़ा त्याग क्यों है?", "image_prompt": "An ancient glowing sage sitting in deep meditation, radiating pure spiritual golden light, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "वृत्रासुर नाम के असुर ने स्वर्ग पर कब्ज़ा कर लिया।", "image_prompt": "A terrifying giant demon, Vritrasura, sitting on the throne of Heaven (Swarga), dark storm clouds, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उसे किसी साधारण अस्त्र से नहीं मारा जा सकता था।", "image_prompt": "Swords, arrows, and spears shattering into pieces upon hitting the demon''s impenetrable skin, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "इंद्र देव भगवान विष्णु के पास गए।", "image_prompt": "Lord Indra looking defeated, kneeling before Lord Vishnu who is resting on the cosmic serpent Shesha, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "विष्णु जी ने एक अनोखा उपाय बताया।", "image_prompt": "Lord Vishnu speaking, glowing with divine blue light, explaining the secret weapon to Indra, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "वृत्रासुर को केवल तपस्वी की हड्डियों से बने वज्र से मारा जा सकता था।", "image_prompt": "A glowing, magical, indestructible weapon (Vajra) made of pure white divine bone, floating in light, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "देवता महर्षि दधीचि के पास पहुँचे।", "image_prompt": "The gods folding hands and pleading before Sage Dadhichi in his peaceful forest ashram, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "इंद्र ने उनसे उनकी हड्डियाँ माँगी।", "image_prompt": "Lord Indra looking shameful but desperate, asking the ultimate sacrifice from the calm sage, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "दधीचि ने मुस्कुराते हुए अपना शरीर त्याग दिया।", "image_prompt": "Sage Dadhichi meditating, his soul leaving his body as a glowing golden orb, peaceful and fearless, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "देवताओं ने उनकी रीढ़ की हड्डी से ''वज्र'' बनाया।", "image_prompt": "Vishwakarma (the divine architect) forging the glowing Vajra weapon from the sage''s spine, magical sparks, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "इसी वज्र से वृत्रासुर का वध हुआ।", "image_prompt": "Lord Indra flying in the sky and striking the giant demon Vritrasura with the blinding Vajra, epic battle, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "धर्म की रक्षा के लिए किया गया त्याग ही महान है।", "image_prompt": "A glowing lotus blooming over a pile of bones, symbolizing eternal glory through sacrifice, 9:16", "approx_sec": 6.0}]}' WHERE id = 'dadhichi_bones';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "markandeya_mrityunjaya", "title": "मार्कण्डेय और महामृत्युंजय मंत्र", "category": "शिव पुराण", "script_hi": "महामृत्युंजय मंत्र की उत्पत्ति कैसे हुई? ऋषि मृकंडु को कोई संतान नहीं थी। उन्होंने भगवान शिव की तपस्या की। शिव जी ने उन्हें दो विकल्प दिए: या तो एक मूर्ख पुत्र जो 100 साल जिएगा, या एक अत्यंत ज्ञानी पुत्र जिसकी आयु केवल 16 वर्ष होगी। ऋषि ने ज्ञानी पुत्र को चुना, जिसका नाम मार्कण्डेय रखा गया। मार्कण्डेय बचपन से ही शिव के परम भक्त थे। जब वे 16 वर्ष के हुए, तो यमराज उनके प्राण लेने आए। मार्कण्डेय उस समय शिवलिंग की पूजा कर रहे थे। यमराज का पाश देखकर वे डर गए और शिवलिंग से लिपट गए। उन्होंने मृत्यु को हराने वाला महामृत्युंजय मंत्र जपना शुरू कर दिया। जैसे ही यमराज ने अपना पाश शिवलिंग पर फेंका, शिवलिंग फट गया और उसमें से साक्षात भगवान शिव भयंकर रूप में प्रकट हुए! शिव जी ने क्रोध में आकर यमराज पर त्रिशूल तान दिया। महादेव ने मार्कण्डेय को हमेशा 16 वर्ष के रहने और अमरता का वरदान दिया। तभी से महामृत्युंजय मंत्र को मृत्यु पर विजय पाने वाला सबसे शक्तिशाली मंत्र माना जाता है।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "महामृत्युंजय मंत्र की उत्पत्ति कैसे हुई?", "image_prompt": "A glowing ancient palm leaf manuscript with glowing Sanskrit mantras, mystical blue lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "ऋषि मृकंडु ने शिव की तपस्या की।", "image_prompt": "An ancient sage meditating deeply in a forest, Lord Shiva appearing in front of him in a glowing form, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उन्होंने 16 वर्ष की आयु वाले ज्ञानी पुत्र को चुना।", "image_prompt": "A beautiful, intelligent young boy dressed as a young sage, holding a prayer bead necklace (Rudraksha), 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "मार्कण्डेय शिव के परम भक्त थे।", "image_prompt": "Young boy Markandeya devotedly offering water and bel leaves to a dark stone Shiva Linga, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "जब वे 16 वर्ष के हुए, यमराज प्राण लेने आए।", "image_prompt": "Yamaraja, the God of Death, riding a giant black water buffalo, looking terrifying, holding a noose, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "यमराज का पाश देखकर मार्कण्डेय शिवलिंग से लिपट गए।", "image_prompt": "Terrified boy Markandeya hugging the Shiva Linga tightly, eyes closed, chanting mantras loudly, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "उन्होंने महामृत्युंजय मंत्र जपना शुरू किया।", "image_prompt": "Glowing cosmic sound waves of the mantra expanding from the boy, hitting the dark presence of death, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "यमराज ने अपना पाश शिवलिंग पर फेंका।", "image_prompt": "Yamaraja throwing his glowing dark lasso (Paash) which accidentally wraps around the Shiva Linga, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "तभी शिवलिंग फट गया!", "image_prompt": "The Shiva Linga bursting open with intense blinding white and blue light, cosmic energy exploding, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "भगवान शिव भयंकर रूप में प्रकट हुए।", "image_prompt": "Furious Lord Shiva emerging from the Linga, holding his glowing Trishul and pointing it directly at Yamaraja, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "शिव जी ने मार्कण्डेय को अमरता का वरदान दिया।", "image_prompt": "Lord Shiva calming down, placing his hand on Markandeya''s head, granting him eternal youth and immortality, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यह मंत्र मृत्यु पर विजय पाने वाला है।", "image_prompt": "A glowing third eye symbol radiating protective energy, representing the ultimate triumph over death, 9:16", "approx_sec": 5.0}]}' WHERE id = 'markandeya_mrityunjaya';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "kurma_avatar", "title": "कूर्म अवतार और मंदार पर्वत", "category": "विष्णु पुराण", "script_hi": "भगवान विष्णु को कूर्म (कछुए) का अवतार क्यों लेना पड़ा? महर्षि दुर्वासा के एक श्राप के कारण जब देवराज इंद्र और सभी देवता अपनी शक्ति खो बैठे, तब असुरों ने स्वर्ग पर कब्ज़ा कर लिया। अपनी शक्ति वापस पाने के लिए, विष्णु जी ने देवताओं को असुरों के साथ मिलकर ''समुद्र मंथन'' करने की सलाह दी, ताकि वे अमरता का अमृत पा सकें। इस महामंथन के लिए मंदार पर्वत को मथनी (मथने वाला डंडा) और वासुकि नाग को रस्सी बनाया गया। लेकिन जैसे ही मंदार पर्वत को समुद्र में डाला गया, वह अपने भारी वजन के कारण डूबने लगा। तब मंथन को सफल बनाने के लिए, भगवान विष्णु ने एक विशालकाय कूर्म (कछुए) का रूप धारण किया और समुद्र की गहराई में जाकर मंदार पर्वत को अपनी मजबूत पीठ पर उठा लिया। उनकी पीठ पर यह पर्वत हजारों वर्षों तक घूमता रहा, और अंततः समुद्र से अमृत समेत 14 अनमोल रत्न बाहर निकले।", "estimated_speech_sec": 80.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "विष्णु जी को कूर्म अवतार क्यों लेना पड़ा?", "image_prompt": "A massive glowing divine Tortoise (Kurma) swimming gracefully in the deep cosmic ocean, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "दुर्वासा मुनि के श्राप से देवता शक्तिहीन हो गए थे।", "image_prompt": "Angry Sage Durvasa throwing a garland of flowers to the ground, cursing a shocked Lord Indra, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "विष्णु जी ने समुद्र मंथन करने की सलाह दी।", "image_prompt": "Lord Vishnu instructing gods and demons to cooperate, glowing cosmic ocean in the background, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "मंथन के लिए मंदार पर्वत को मथनी बनाया गया।", "image_prompt": "A colossal mountain (Mandara) being lifted by gods and demons using magic and strength, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "और वासुकि नाग को रस्सी।", "image_prompt": "The giant multi-headed serpent Vasuki wrapping himself around the mountain like a massive rope, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "लेकिन मंदार पर्वत समुद्र में डूबने लगा!", "image_prompt": "The huge mountain sinking fast into the dark, swirling ocean waters, causing panic among the gods, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "तब भगवान विष्णु ने विशाल कूर्म का रूप लिया।", "image_prompt": "Lord Vishnu magically transforming into a gigantic, indestructible sea turtle deep underwater, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "उन्होंने पर्वत को अपनी पीठ पर उठा लिया।", "image_prompt": "The massive Kurma avatar underwater, holding the gigantic sinking mountain securely on its glowing shell, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "हजारों वर्षों तक पर्वत उनकी पीठ पर घूमता रहा।", "image_prompt": "The mountain spinning rapidly on the turtle''s shell, creating giant cosmic whirlpools, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "अंततः समुद्र से 14 अनमोल रत्न बाहर निकले।", "image_prompt": "Glowing magical treasures emerging from the churning waters, lighting up the sky, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "और देवताओं को अमृत प्राप्त हुआ।", "image_prompt": "Lord Dhanvantari emerging from the ocean holding the golden pot (Kalash) filled with Amrita (nectar), 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "यही था कूर्म अवतार का उद्देश्य।", "image_prompt": "A majestic portrait of Lord Vishnu standing above the giant Kurma, radiating cosmic peace, 9:16", "approx_sec": 5.0}]}' WHERE id = 'kurma_avatar';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "narasimha_hiranyakashipu", "title": "नृसिंह अवतार और प्रह्लाद", "category": "विष्णु पुराण", "script_hi": "भगवान विष्णु को आधा नर और आधा सिंह (शेर) क्यों बनना पड़ा? हिरण्यकशिपु नाम के असुर राजा ने ब्रह्मा जी से एक अजीब वरदान मांगा था। उसने मांगा कि वह न दिन में मरे न रात में, न घर के अंदर मरे न बाहर, न अस्त्र से मरे न शस्त्र से, और न किसी इंसान से मरे न जानवर से। इस वरदान के अहंकार में उसने खुद को भगवान घोषित कर दिया और अपने ही विष्णु भक्त बेटे, प्रह्लाद को जान से मारने की कोशिशें करने लगा। जब हिरण्यकशिपु ने प्रह्लाद से पूछा कि ''क्या तेरा भगवान इस खंभे में भी है?'' और उसने खंभे पर गदा मारी, तो उस खंभे को फाड़कर भगवान नृसिंह प्रकट हुए! नृसिंह का रूप न पूरा इंसान था न पूरा जानवर। उन्होंने गोधूलि वेला (न दिन न रात) में, महल की दहलीज पर (न अंदर न बाहर), अपने नाखुनों से (न अस्त्र न शस्त्र), हिरण्यकशिपु का पेट फाड़कर उसका वध कर दिया। भगवान अपने भक्त की रक्षा के लिए किसी भी सीमा तक जा सकते हैं।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "विष्णु जी को आधा नर और आधा सिंह क्यों बनना पड़ा?", "image_prompt": "A terrifying silhouette of a being that is half man and half lion, glowing angry eyes in the dark, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "हिरण्यकशिपु ने एक अजीब वरदान मांगा था।", "image_prompt": "Demon king Hiranyakashipu laughing arrogantly, surrounded by a magical protective shield from Lord Brahma, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उसका बेटा प्रह्लाद विष्णु का परम भक्त था।", "image_prompt": "Little boy Prahlad sitting peacefully with folded hands, chanting prayers, glowing with pure devotion, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "अहंकारी राजा ने प्रह्लाद को मारने की कोशिश की।", "image_prompt": "Hiranyakashipu threatening his little son with a sword, while Prahlad remains completely fearless, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "''क्या तेरा भगवान इस खंभे में भी है?''", "image_prompt": "The furious demon king pointing his mace towards a massive stone pillar in the grand palace, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "खंभे को फाड़कर भगवान नृसिंह प्रकट हुए!", "image_prompt": "The massive stone pillar exploding, Lord Narasimha (half-man half-lion) roaring fiercely, epic divine power, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "यह रूप न इंसान था, न जानवर।", "image_prompt": "Close up of Lord Narasimha''s fierce lion face and powerful human torso, radiating intense fiery energy, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "गोधूलि वेला (न दिन न रात)।", "image_prompt": "The sky outside the palace showing twilight, the sun exactly setting at the horizon, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "दहलीज पर (न अंदर न बाहर)।", "image_prompt": "Lord Narasimha dragging the terrified demon king to the exact threshold (doorway) of the palace, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "नाखुनों से (न अस्त्र न शस्त्र) वध किया।", "image_prompt": "Lord Narasimha sitting on the threshold, tearing open the chest of the demon with his bare sharp claws, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "प्रह्लाद ने उन्हें शांत किया।", "image_prompt": "Little Prahlad lovingly placing a garland around the neck of the still angry but softening Lord Narasimha, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "भगवान भक्त के लिए कोई भी रूप ले सकते हैं।", "image_prompt": "Lord Narasimha licking Prahlad''s face affectionately like a mother lion, divine love and protection, 9:16", "approx_sec": 5.0}]}' WHERE id = 'narasimha_hiranyakashipu';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "vamana_bali", "title": "वामन अवतार और राजा बलि", "category": "विष्णु पुराण", "script_hi": "भगवान विष्णु ने एक छोटे से ब्राह्मण का अवतार क्यों लिया? प्रह्लाद के पोते, असुर राजा बलि ने अपनी शक्तियों से स्वर्ग पर कब्ज़ा कर लिया था। यद्यपि बलि एक असुर था, लेकिन वह बहुत दानी और धर्मात्मा था। देवताओं को उनका स्वर्ग वापस दिलाने के लिए, विष्णु जी ने ''वामन'' (बौने ब्राह्मण) का रूप धारण किया और राजा बलि के यज्ञ में पहुंच गए। बलि ने उनसे कुछ भी मांगने को कहा। वामन ने मुस्कुराकर केवल अपने पैरों से नापने भर ''तीन पग ज़मीन'' मांगी। बलि के गुरु शुक्राचार्य वामन की असलियत समझ गए और उन्होंने बलि को रोका, लेकिन बलि अपने वचन से नहीं मुकरा। जैसे ही बलि ने संकल्प पूरा किया, वामन का आकार अचानक से बढ़ने लगा! उन्होंने अपने पहले पग में पूरी धरती नाप ली, और दूसरे पग में स्वर्ग और पूरा ब्रह्मांड नाप लिया। जब तीसरे पग के लिए कोई जगह नहीं बची, तो बलि ने विनम्रता से अपना सिर आगे कर दिया। वामन ने अपना पैर उसके सिर पर रखा और उसे पाताल लोक का राजा बना दिया।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "विष्णु जी ने वामन अवतार क्यों लिया?", "image_prompt": "A cute, small dwarf Brahmin boy (Vamana) holding an umbrella made of leaves, smiling purely, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "असुर राजा बलि ने स्वर्ग पर कब्ज़ा कर लिया था।", "image_prompt": "Demon King Bali, grand and heavily jeweled, sitting powerfully on Indra''s throne in heaven, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "लेकिन वह बहुत दानी और धर्मात्मा था।", "image_prompt": "King Bali generously giving away gold and cows to priests in a grand fire sacrifice (Yagna), 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "वामन भगवान बलि के यज्ञ में पहुंचे।", "image_prompt": "The dwarf Brahmin Vamana walking into the grand royal sacrifice area, radiating divine simplicity, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "उन्होंने केवल तीन पग (कदम) ज़मीन मांगी।", "image_prompt": "Vamana pointing to his small feet and asking the giant King Bali for three paces of land, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "गुरु शुक्राचार्य ने बलि को चेतावनी दी।", "image_prompt": "Guru Shukracharya whispering anxiously into Bali''s ear, warning him about Lord Vishnu''s trick, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "लेकिन बलि अपने वचन से पीछे नहीं हटा।", "image_prompt": "King Bali proudly pouring sacred water from a pot to finalize the vow, ignoring his guru, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "तभी वामन का आकार विशाल होने लगा!", "image_prompt": "Vamana magically growing in size, expanding beyond the clouds, towering over the entire kingdom, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "पहले पग में पूरी धरती नाप ली।", "image_prompt": "One gigantic foot of Lord Vishnu covering the entire globe of the Earth, cosmic scale, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "दूसरे पग में स्वर्ग और ब्रह्मांड नाप लिया।", "image_prompt": "The second foot reaching up into the galaxies, touching the highest heavens, epic scale, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "तीसरे पग के लिए बलि ने अपना सिर आगे कर दिया।", "image_prompt": "King Bali kneeling humbly with folded hands, offering his head for the giant glowing foot to step on, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "भगवान ने उसे पाताल का राजा बना दिया।", "image_prompt": "Lord Vishnu blessing Bali in Patala Loka (underworld), surrounded by glowing crystals and wealth, 9:16", "approx_sec": 5.0}]}' WHERE id = 'vamana_bali';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "parashurama_rage", "title": "परशुराम का क्रोध", "category": "विष्णु पुराण", "script_hi": "भगवान परशुराम ने क्षत्रियों का विनाश क्यों किया? परशुराम भगवान विष्णु के छठे अवतार थे। उनके पिता ऋषि जमदग्नि के पास ''कामधेनु'' नाम की एक चमत्कारी गाय थी, जो किसी भी इच्छा को पूरा कर सकती थी। एक दिन, सहस्रार्जुन नाम का एक अहंकारी और क्रूर क्षत्रिय राजा ऋषि के आश्रम में आया। उसने बलपूर्वक वह चमत्कारी गाय छीन ली और ऋषि का अपमान किया। जब परशुराम वापस लौटे और उन्हें यह बात पता चली, तो उनका क्रोध भड़क उठा। वे अकेले ही सहस्रार्जुन की राजधानी महिष्मती पहुंच गए और अपने भयंकर ''फरसे'' (Parashu) से उस राजा की हज़ार भुजाएँ काट डालीं और उसका वध कर दिया। लेकिन बात यहीं नहीं रुकी। राजा के पुत्रों ने बदला लेने के लिए परशुराम की अनुपस्थिति में उनके पिता ऋषि जमदग्नि की हत्या कर दी। इस जघन्य पाप को देखकर परशुराम ने भयंकर प्रतिज्ञा ली। उन्होंने 21 बार पूरी पृथ्वी को क्रूर और अहंकारी क्षत्रिय राजाओं से विहीन कर दिया। यह अवतार धर्म की रक्षा और अन्याय के खिलाफ भयंकर क्रोध का प्रतीक है।", "estimated_speech_sec": 85.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "परशुराम ने क्षत्रियों का विनाश क्यों किया?", "image_prompt": "Lord Parashurama standing fiercely, holding a massive glowing axe (Parashu), intense angry eyes, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "उनके पिता के पास एक चमत्कारी गाय थी।", "image_prompt": "Sage Jamadagni in a peaceful ashram petting the glowing divine wish-fulfilling cow, Kamadhenu, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "सहस्रार्जुन नाम का अहंकारी राजा आश्रम आया।", "image_prompt": "An arrogant king with a thousand arms (Sahasrarjuna) entering the peaceful ashram with his dark army, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "उसने बलपूर्वक गाय को छीन लिया।", "image_prompt": "Cruel soldiers forcefully dragging the crying divine cow away from the helpless old sage, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "परशुराम का क्रोध भड़क उठा!", "image_prompt": "Lord Parashurama discovering the crime, his eyes burning with intense red fire, lightning cracking behind him, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "वे अकेले ही राजा की राजधानी पहुंच गए।", "image_prompt": "Parashurama walking fearlessly alone towards a massive fortress, holding his glowing axe, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "अपने फरसे से राजा की हज़ार भुजाएँ काट डालीं।", "image_prompt": "Parashurama spinning his axe at lightning speed, slicing through the thousand arms of the giant king, epic battle, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "लेकिन राजा के पुत्रों ने बदला लिया।", "image_prompt": "The evil sons of the king sneaking into the ashram at night, holding bloodied swords, cowardly act, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "उन्होंने ऋषि जमदग्नि की हत्या कर दी।", "image_prompt": "Lord Parashurama falling to his knees and weeping loudly while holding the lifeless body of his father, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "परशुराम ने भयंकर प्रतिज्ञा ली।", "image_prompt": "Parashurama standing up, raising his axe to the sky, blood on his face, taking a terrible vow, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "उन्होंने 21 बार पृथ्वी को क्रूर राजाओं से विहीन किया।", "image_prompt": "Parashurama destroying armies of arrogant kings, chaotic battlefield, justice being served, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यह अन्याय के खिलाफ क्रोध का प्रतीक है।", "image_prompt": "A majestic cinematic portrait of Parashurama as a symbol of divine justice and unstoppable wrath, 9:16", "approx_sec": 5.0}]}' WHERE id = 'parashurama_rage';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "dhruva_star", "title": "भक्त ध्रुव और ध्रुव तारा", "category": "विष्णु पुराण", "script_hi": "आसमान में सबसे स्थिर चमकने वाला ''ध्रुव तारा'' कौन है? राजा उत्तानपाद की दो पत्नियां थीं - सुनीति और सुरुचि। राजा सुरुचि को अधिक प्रेम करते थे। एक दिन सुनीति का पांच साल का बेटा, ध्रुव, अपने पिता की गोद में बैठने गया। लेकिन सौतेली माँ सुरुचि ने उसे अपमानित करके वहाँ से धक्का दे दिया और कहा, ''राजा की गोद में बैठने के लिए तुझे मेरे गर्भ से जन्म लेना चाहिए था!'' रोता हुआ बालक ध्रुव अपनी असली माँ के पास गया। माँ ने कहा, ''अगर तुम्हें कोई सच्चा स्थान दे सकता है, तो वो सिर्फ भगवान विष्णु हैं।'' 5 साल का ध्रुव तुरंत जंगल की ओर निकल पड़ा। उसने बिना कुछ खाए-पिए महीनों तक भगवान विष्णु की घोर तपस्या की। उसकी भक्ति की तपिश से पूरा ब्रह्मांड हिलने लगा। अंततः भगवान विष्णु साक्षात प्रकट हुए और उन्होंने उस छोटे से बालक को दर्शन दिए। भगवान ने ध्रुव को आशीर्वाद दिया कि उसे ब्रह्मांड में एक ऐसा स्थान मिलेगा जो कभी नहीं हिलेगा। उसी बालक को आज हम ब्रह्मांड के सबसे स्थिर ''ध्रुव तारे'' (Pole Star) के रूप में देखते हैं।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "आसमान में सबसे स्थिर ''ध्रुव तारा'' कौन है?", "image_prompt": "A magical night sky focusing on one incredibly bright, unmoving star (Pole Star) surrounded by swirling galaxies, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "राजा उत्तानपाद का पांच साल का बेटा था ध्रुव।", "image_prompt": "A cute 5-year-old royal prince, Dhruva, looking lovingly towards his father who is sitting on a throne, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "वह अपने पिता की गोद में बैठने गया।", "image_prompt": "Little Dhruva happily running and trying to climb onto the lap of the King, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "सौतेली माँ सुरुचि ने उसे धक्का दे दिया।", "image_prompt": "The evil stepmother angrily pushing the crying little boy away from the throne, arrogant expression, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "''तुम्हें मेरे गर्भ से जन्म लेना चाहिए था!''", "image_prompt": "Stepmother pointing a finger down at the crying boy, harsh and insulting, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "माँ ने कहा, सच्चा स्थान सिर्फ भगवान दे सकते हैं।", "image_prompt": "Dhruva''s real mother wiping his tears and pointing up towards the heavens, instilling faith in him, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "5 साल का ध्रुव जंगल की ओर निकल पड़ा।", "image_prompt": "The little brave prince walking alone into a deep, dark, scary forest at night, fearless, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "उसने महीनों तक विष्णु की घोर तपस्या की।", "image_prompt": "Little Dhruva sitting in deep meditation on one leg, glowing with a golden spiritual aura, surrounded by wild animals, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "उसकी भक्ति से ब्रह्मांड हिलने लगा।", "image_prompt": "Cosmic energy radiating from the small meditating boy, shaking the stars and planets, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "अंततः भगवान विष्णु साक्षात प्रकट हुए।", "image_prompt": "Lord Vishnu appearing in all his glory, riding Garuda, glowing beautifully in front of the little boy, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "भगवान ने उसे एक अटल स्थान का आशीर्वाद दिया।", "image_prompt": "Lord Vishnu affectionately touching the boy''s head, granting him the eternal position in the cosmos, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "वही बालक आज ''ध्रुव तारा'' है।", "image_prompt": "The glowing boy magically transforming into the eternal, bright Pole star, shining eternally in the sky, 9:16", "approx_sec": 5.0}]}' WHERE id = 'dhruva_star';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "satyavan_savitri", "title": "सावित्री और सत्यवान की कथा", "category": "पौराणिक कथा", "script_hi": "सच्चे प्रेम और दृढ़ निश्चय की सबसे बड़ी कहानी - सावित्री और सत्यवान। राजकुमारी सावित्री ने एक गरीब और निर्वासित राजकुमार, सत्यवान को अपने पति के रूप में चुना। लेकिन नारद मुनि ने चेतावनी दी कि सत्यवान की आयु केवल एक वर्ष शेष है। फिर भी, सावित्री नहीं मानीं और खुशी-खुशी विवाह कर लिया। ठीक एक साल बाद, जब सत्यवान जंगल में लकड़ी काट रहे थे, उनके सिर में भयंकर दर्द हुआ और वे सावित्री की गोद में गिर पड़े। उसी समय स्वयं यमराज सत्यवान के प्राण लेने आए। जब यमराज सत्यवान की आत्मा लेकर जाने लगे, तो सावित्री भी उनके पीछे-पीछे चलने लगीं। यमराज ने उन्हें वापस जाने को कहा, लेकिन सावित्री ने धर्म, कर्म और पतिव्रता ज्ञान पर यमराज से ऐसा अद्भुत तर्क-वितर्क किया कि मृत्यु के देवता भी उनके ज्ञान से प्रसन्न हो गए। यमराज ने उन्हें तीन वरदान दिए। अपनी चतुराई से सावित्री ने तीसरे वरदान में ''सौ पुत्रों'' का वरदान मांग लिया। वरदान पूरा करने के लिए यमराज को विवश होकर सत्यवान के प्राण वापस लौटाने पड़े। यह कहानी बताती है कि बुद्धि और भक्ति से मृत्यु को भी हराया जा सकता है।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "सच्चे प्रेम की सबसे बड़ी कहानी", "image_prompt": "A beautiful ancient Indian princess, Savitri, looking lovingly at a handsome, simple woodcutter prince, Satyavan, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "नारद मुनि ने सावित्री को चेतावनी दी...", "image_prompt": "Sage Narada holding his Veena, warning the princess with a serious expression, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "कि सत्यवान की आयु केवल एक वर्ष शेष है।", "image_prompt": "An hourglass with sand quickly running out, symbolic of limited time and approaching death, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "फिर भी सावित्री ने खुशी-खुशी विवाह किया।", "image_prompt": "Savitri and Satyavan getting married simply in a forest hermitage, exchanging flower garlands, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "एक साल बाद जंगल में...", "image_prompt": "Satyavan cutting wood with an axe in a dense forest, looking suddenly tired and dizzy, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "सत्यवान सावित्री की गोद में गिर पड़े।", "image_prompt": "Satyavan collapsing into Savitri''s lap, unconscious, under a large banyan tree, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "स्वयं यमराज उनके प्राण लेने आए।", "image_prompt": "Yamaraja, the God of Death, towering over them, holding his noose, glowing with a dark green aura, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "सावित्री भी यमराज के पीछे-पीछे चलने लगीं।", "image_prompt": "Yamaraja walking away with a glowing soul, and brave Savitri following him closely on a dark path, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "यमराज ने उन्हें वापस जाने को कहा।", "image_prompt": "Yamaraja stopping and holding up his hand, commanding her to turn back, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "सावित्री ने धर्म और ज्ञान पर अद्भुत तर्क किया।", "image_prompt": "Savitri speaking confidently and respectfully to Yamaraja, radiating intelligence and devotion, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "यमराज को सत्यवान के प्राण लौटाने पड़े।", "image_prompt": "Yamaraja smiling in defeat and releasing the glowing soul back into Satyavan''s body, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "बुद्धि और भक्ति से मृत्यु को भी हराया जा सकता है।", "image_prompt": "Satyavan waking up in Savitri''s arms, the forest glowing with warm sunlight and new life, 9:16", "approx_sec": 5.0}]}' WHERE id = 'satyavan_savitri';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "sita_swayamvar", "title": "सीता स्वयंवर और शिव धनुष", "category": "रामायण कथा", "script_hi": "सीता स्वयंवर में शिव धनुष का क्या रहस्य था? राजा जनक की पुत्री सीता कोई साधारण कन्या नहीं थीं। वे भूमि से प्रकट हुई थीं। बचपन में ही सीता ने खेलते-खेलते भगवान शिव का वो विशाल और अत्यंत भारी धनुष (पिनाक) उठा लिया था, जिसे बड़े-बड़े योद्धा हिला तक नहीं सकते थे। राजा जनक ने तभी यह प्रतिज्ञा ले ली थी कि जो वीर इस शिव धनुष पर प्रत्यंचा (डोरी) चढ़ाएगा, उसी से सीता का विवाह होगा। स्वयंवर के दिन, दुनिया भर के महान राजा और योद्धा आए। अहंकार में चूर बड़े-बड़े राजाओं ने कोशिश की, लेकिन कोई उस धनुष को तिल भर भी हिला नहीं सका। रावण भी इस स्वयंवर में आया था, लेकिन वह भी असफल रहा। तब ऋषि विश्वामित्र के आदेश पर, मर्यादा पुरुषोत्तम श्री राम सभा के बीच आए। राम ने बड़ी ही शालीनता से धनुष को प्रणाम किया। जैसे ही उन्होंने उसे बीच से उठाकर मोड़ा, वह महाविशाल शिव धनुष एक भयंकर गर्जना के साथ टूट गया! इस तरह राम और सीता का अद्भुत मिलन हुआ।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "सीता स्वयंवर में शिव धनुष का क्या रहस्य था?", "image_prompt": "A massive, heavy, beautifully carved divine bow of Lord Shiva (Pinaka) resting on a grand pedestal, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "बचपन में सीता ने खेलते हुए वह धनुष उठा लिया था।", "image_prompt": "A little girl, Sita, effortlessly lifting the giant heavy bow with one hand while playing with a ball, 9:16", "approx_sec": 6.0}, {"slide_index": 3, "caption": "राजा जनक ने प्रतिज्ञा ले ली...", "image_prompt": "King Janaka looking stunned and deciding on the Swayamvar, royal palace setting, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "जो इस धनुष पर डोरी चढ़ाएगा, उसी से विवाह होगा।", "image_prompt": "A grand royal assembly (Swayamvar Sabha) filled with arrogant kings looking at the giant bow, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "बड़े-बड़े राजाओं ने कोशिश की।", "image_prompt": "Muscular kings struggling and sweating, trying to lift the bow but failing miserably, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "कोई उसे तिल भर भी हिला नहीं सका।", "image_prompt": "The bow sitting perfectly still, looking incredibly heavy and immovable, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "रावण भी इस स्वयंवर में असफल रहा।", "image_prompt": "The mighty demon king Ravana trying to lift the bow, looking embarrassed and angry as he fails, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "तब ऋषि विश्वामित्र के आदेश पर श्री राम आए।", "image_prompt": "Sage Vishwamitra nodding to Lord Rama, Rama standing up calmly with a serene smile, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "राम ने बड़ी शालीनता से धनुष को प्रणाम किया।", "image_prompt": "Lord Rama bowing respectfully with folded hands to the divine bow of Lord Shiva, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "जैसे ही उन्होंने उसे उठाकर मोड़ा...", "image_prompt": "Lord Rama effortlessly picking up the massive bow and bending it to string it, muscles flexing, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "धनुष भयंकर गर्जना के साथ टूट गया!", "image_prompt": "The massive bow snapping perfectly in half, a blinding flash of light and thunder, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "इस तरह राम और सीता का अद्भुत मिलन हुआ।", "image_prompt": "Goddess Sita shyly putting the beautiful flower garland (Varmala) around Lord Rama''s neck, 9:16", "approx_sec": 5.0}]}' WHERE id = 'sita_swayamvar';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ahilya_redemption", "title": "अहिल्या का उद्धार", "category": "रामायण कथा", "script_hi": "पत्थर बनी अहिल्या को श्री राम ने कैसे मुक्ति दी? अहिल्या गौतम ऋषि की अत्यंत सुंदर और पवित्र पत्नी थीं। एक दिन जब गौतम ऋषि आश्रम में नहीं थे, तब देवराज इंद्र ने छल से गौतम ऋषि का वेश धारण किया और आश्रम में प्रवेश किया। जब ऋषि वापस आए और उन्होंने यह सब देखा, तो क्रोध में आकर उन्होंने अहिल्या को श्राप दे दिया कि वह एक निर्जीव पत्थर बन जाएगी। अहिल्या रोती रहीं, क्योंकि उनके साथ छल हुआ था। तब ऋषि को दया आई और उन्होंने कहा, ''त्रेता युग में जब साक्षात भगवान विष्णु, श्री राम के अवतार में यहां आएंगे, तब उनके चरणों की धूल से तुम्हारा उद्धार होगा।'' हज़ारों वर्षों तक अहिल्या एक पत्थर के रूप में उस वीरान आश्रम में तपस्या करती रहीं। अंततः, जब श्री राम विश्वामित्र जी के साथ जनकपुर जा रहे थे, तब वे उस आश्रम में पहुंचे। जैसे ही श्री राम के पावन चरणों की धूल उस पत्थर पर पड़ी, वह पत्थर एक खूबसूरत स्त्री में बदल गया! अहिल्या ने हाथ जोड़कर भगवान राम की स्तुति की और अंततः उन्हें मोक्ष प्राप्त हुआ।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "पत्थर बनी अहिल्या को श्री राम ने कैसे मुक्ति दी?", "image_prompt": "A beautiful ancient Indian woman partially turned into a grey stone statue in a forest, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "अहिल्या गौतम ऋषि की सुंदर पत्नी थीं।", "image_prompt": "A beautiful pious woman praying peacefully in an ancient forest ashram, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "देवराज इंद्र ने छल से ऋषि का वेश धारण किया।", "image_prompt": "Lord Indra looking sneaky, magically transforming his face to look exactly like Sage Gautam, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "क्रोधित ऋषि ने अहिल्या को श्राप दे दिया।", "image_prompt": "Sage Gautam furiously throwing holy water from his kamandalu, cursing crying Ahilya, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "''तुम एक निर्जीव पत्थर बन जाओगी!''", "image_prompt": "Ahilya slowly turning into a solid grey rock, looking helpless and innocent, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "ऋषि ने कहा, राम के चरणों से उद्धार होगा।", "image_prompt": "The sage looking slightly regretful, pointing towards the future, mystical lighting, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "हज़ारों वर्षों तक अहिल्या पत्थर बनी रहीं।", "image_prompt": "A solitary rock shaped like a woman covered in moss and vines in an abandoned, dark forest, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "अंततः श्री राम उस आश्रम में पहुंचे।", "image_prompt": "Lord Rama and Lakshmana, glowing with divine light, walking into the dark, abandoned ashram, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "जैसे ही राम के चरणों की धूल पत्थर पर पड़ी...", "image_prompt": "Lord Rama''s glowing lotus feet touching the edge of the stone, magical golden dust floating, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "पत्थर एक खूबसूरत स्त्री में बदल गया!", "image_prompt": "The grey stone shattering with a blinding light, revealing the pure and radiant Ahilya, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "अहिल्या ने हाथ जोड़कर स्तुति की।", "image_prompt": "Ahilya kneeling on the ground with folded hands, crying tears of joy, looking up at Lord Rama, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "और अंततः उन्हें मोक्ष प्राप्त हुआ।", "image_prompt": "A glowing soul rising towards the heavens, feeling completely free and liberated, 9:16", "approx_sec": 5.0}]}' WHERE id = 'ahilya_redemption';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "jatayu_sacrifice", "title": "जटायु का बलिदान", "category": "रामायण कथा", "script_hi": "रामायण में गिद्धराज जटायु का बलिदान क्यों इतना महान है? जब रावण माता सीता का हरण करके उन्हें पुष्पक विमान में लंका ले जा रहा था, तब सीता जी ने मदद के लिए पुकार लगाई। उनकी आवाज़ सुनकर वृद्ध जटायु वहां आ गए। जटायु जानते थे कि रावण एक अत्यंत शक्तिशाली राक्षस है और वे अब बहुत बूढ़े हो चुके हैं। फिर भी, एक असहाय स्त्री की रक्षा करना उन्होंने अपना धर्म समझा। जटायु ने रावण के रथ पर भयंकर हमला कर दिया। उन्होंने अपने पंजों और चोंच से रावण को लहूलुहान कर दिया और उसका रथ तोड़ डाला। अंततः रावण ने छल से अपनी तलवार निकालकर जटायु के दोनों पंख काट दिए। जटायु लहूलुहान होकर ज़मीन पर गिर पड़े। जब भगवान राम सीता को खोजते हुए वहां पहुंचे, तब प्राण त्यागने से पहले जटायु ने ही राम को बताया कि रावण सीता को दक्षिण दिशा की ओर ले गया है। श्री राम ने पिता के समान जटायु का अंतिम संस्कार अपने हाथों से किया। जटायु का बलिदान सिखाता है कि परिणाम चाहे जो हो, धर्म और रक्षा के लिए लड़ना ही असली वीरता है।", "estimated_speech_sec": 85.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "गिद्धराज जटायु का बलिदान महान क्यों है?", "image_prompt": "A majestic giant vulture (Jatayu) flying in the ancient Indian skies, wise and powerful, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "रावण पुष्पक विमान में सीता का हरण कर रहा था।", "image_prompt": "Demon king Ravana flying in his magical floating chariot (Pushpaka Vimana) with a captive Goddess Sita, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "सीता जी ने मदद के लिए पुकार लगाई।", "image_prompt": "Goddess Sita looking out of the flying chariot, crying and throwing her jewelry down as a trail, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "वृद्ध जटायु ने उनकी आवाज़ सुनी।", "image_prompt": "Old but strong Jatayu perched on a high mountain cliff, looking up sharply at the sky with fierce eyes, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "जटायु ने बिना डरे रावण पर हमला कर दिया।", "image_prompt": "Jatayu flying fiercely towards Ravana''s chariot, clashing mid-air, dynamic action scene, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "उन्होंने रावण के रथ को तोड़ डाला।", "image_prompt": "Jatayu using his sharp talons and beak to destroy the wooden parts of the magical chariot, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "लेकिन रावण ने छल से तलवार निकाल ली।", "image_prompt": "Furious Ravana drawing a large glowing dark sword, preparing to strike the giant bird, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "और जटायु के दोनों पंख काट दिए।", "image_prompt": "Ravana slashing the sword, cutting Jatayu''s massive wings, blood in the air, tragic moment, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "जटायु ज़मीन पर गिर पड़े।", "image_prompt": "The giant wounded bird falling heavily into the forest dirt, losing his strength, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "श्री राम ने उन्हें खोजते हुए पाया।", "image_prompt": "Lord Rama kneeling down in the forest, gently resting the dying Jatayu''s head on his lap, crying, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "जटायु ने रावण की दिशा बताई।", "image_prompt": "Jatayu weakly pointing his wing towards the South, speaking his final words to Lord Rama, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "श्री राम ने अपने हाथों से अंतिम संस्कार किया।", "image_prompt": "Lord Rama performing the holy cremation rituals for Jatayu, fire glowing, divine respect, 9:16", "approx_sec": 5.0}]}' WHERE id = 'jatayu_sacrifice';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "kumbhakarna_sleep", "title": "कुंभकर्ण की नींद का रहस्य", "category": "रामायण कथा", "script_hi": "रावण का भाई कुंभकर्ण 6 महीने सोता और 1 दिन क्यों जागता था? कुंभकर्ण एक विशाल और अत्यंत शक्तिशाली राक्षस था, जिसके शरीर और भूख का कोई अंत नहीं था। एक बार कुंभकर्ण ने अपने भाई रावण और विभीषण के साथ ब्रह्मा जी की घोर तपस्या की। ब्रह्मा जी प्रसन्न होकर वरदान देने आए। लेकिन देवी सरस्वती जानती थीं कि अगर कुंभकर्ण ने कोई भयंकर वरदान मांग लिया, तो वह भूख से पूरी दुनिया को खा जाएगा। इसलिए सरस्वती जी ने कुंभकर्ण की जीभ (वाणी) पर वास कर लिया। कुंभकर्ण असल में ब्रह्मा जी से ''इंद्रासन'' (इंद्र का सिंहासन) मांगना चाहता था, लेकिन सरस्वती के प्रभाव के कारण उसके मुँह से ''निद्रासन'' (हमेशा की नींद) निकल गया! ब्रह्मा जी ने तुरंत ''तथास्तु'' कह दिया। रावण ने ब्रह्मा जी से विनती की कि वे इस वरदान को थोड़ा बदल दें। तब ब्रह्मा जी ने वरदान में सुधार किया कि कुंभकर्ण 6 महीने तक सोएगा और सिर्फ 1 दिन के लिए जागेगा। जब रामायण के युद्ध में उसे जगाया गया, तो उसने रावण को समझाया था कि राम साक्षात ईश्वर हैं, लेकिन फिर भी उसने एक भाई के नाते रावण की तरफ से युद्ध किया और वीरगति को प्राप्त हुआ।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कुंभकर्ण 6 महीने क्यों सोता था?", "image_prompt": "A gigantic, muscular demon, Kumbhakarna, sleeping heavily inside a massive, dark cave, snoring loudly, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "वह एक विशाल और शक्तिशाली राक्षस था।", "image_prompt": "Kumbhakarna walking, his footsteps shaking the earth, towering over normal sized trees and humans, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उसने ब्रह्मा जी की घोर तपस्या की।", "image_prompt": "Kumbhakarna standing on one leg in a forest, meditating with folded hands, fire all around him, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "ब्रह्मा जी प्रसन्न होकर वरदान देने आए।", "image_prompt": "Lord Brahma appearing in the sky, sitting on a lotus, glowing with divine golden light, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "सरस्वती जी को चिंता हुई कि यह दुनिया खा जाएगा।", "image_prompt": "Goddess Saraswati holding her Veena, looking worried from the heavens down at the hungry demon, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "उन्होंने कुंभकर्ण की जीभ पर वास कर लिया।", "image_prompt": "A magical glowing white aura of Goddess Saraswati entering the mouth of Kumbhakarna, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "वह ''इंद्रासन'' मांगना चाहता था...", "image_prompt": "A thought bubble of Kumbhakarna showing him sitting proudly on the golden throne of heaven, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "पर मुँह से ''निद्रासन'' निकल गया!", "image_prompt": "Kumbhakarna speaking the wrong word, looking immediately confused and shocked at himself, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "ब्रह्मा जी ने ''तथास्तु'' कह दिया।", "image_prompt": "Lord Brahma raising his right hand and granting the boon, golden magical dust sealing the fate, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "रावण के कहने पर वरदान में सुधार हुआ।", "image_prompt": "Ravana pleading with Lord Brahma, and Brahma holding up 6 fingers indicating 6 months of sleep, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "युद्ध में उठने पर उसने रावण को सच बताया।", "image_prompt": "A giant Kumbhakarna eating massive piles of food while advising Ravana that Rama is God, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "फिर भी भाई के लिए लड़कर वीरगति पाई।", "image_prompt": "Giant Kumbhakarna fighting bravely on the battlefield of Lanka, holding a massive mace, loyal to the end, 9:16", "approx_sec": 5.0}]}' WHERE id = 'kumbhakarna_sleep';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "ravana_shiva_tandava", "title": "रावण और शिव तांडव स्तोत्र", "category": "शिव पुराण", "script_hi": "शिव तांडव स्तोत्र की रचना रावण ने किस भयंकर परिस्थिति में की थी? लंकापति रावण अत्यंत अभिमानी और शक्तिशाली था। एक बार वह अपने पुष्पक विमान में जा रहा था, लेकिन उसका विमान कैलाश पर्वत के ऊपर से नहीं जा सका क्योंकि वहां शिव और पार्वती बैठे थे। रावण के अहंकार को ठेस पहुंची और उसने सोचा कि वह पूरे कैलाश पर्वत को ही उखाड़ कर लंका ले जाएगा! उसने अपनी बीस भुजाओं से कैलाश को नीचे से उठा लिया। पर्वत हिलने लगा। तब भगवान शिव ने मुस्कुराते हुए केवल अपने पैर का अंगूठा पर्वत पर दबा दिया। शिव के अंगूठे का भार इतना भयंकर था कि पर्वत वापस अपनी जगह बैठ गया और रावण के हाथ पर्वत के नीचे बुरी तरह कुचले गए। रावण दर्द से भयंकर चीखने लगा, जिसकी आवाज़ पूरे ब्रह्मांड में गूंज गई। जब रावण को एहसास हुआ कि वह साक्षात महादेव से टकराया है, तो उसने क्षमा मांगने के लिए संस्कृत में एक अत्यंत शक्तिशाली और लयबद्ध कविता गानी शुरू की, जिसे ''शिव तांडव स्तोत्र'' कहा जाता है। उसकी इस अनन्य भक्ति से प्रसन्न होकर शिव ने उसे माफ कर दिया और उसे एक शक्तिशाली तलवार ''चंद्रहास'' भेंट की।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "शिव तांडव स्तोत्र की रचना कैसे हुई?", "image_prompt": "Demon King Ravana singing passionately with his 10 heads, magical glowing Sanskrit verses floating in the air, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "रावण पुष्पक विमान में जा रहा था।", "image_prompt": "Ravana flying proudly in his magnificent floating Vimana above the clouds, arrogant expression, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "कैलाश पर्वत ने उसका रास्ता रोक दिया।", "image_prompt": "The majestic, glowing, snow-covered Mount Kailash standing tall, blocking the path of the Vimana, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "अहंकारी रावण ने पर्वत को उखाड़ने की ठानी।", "image_prompt": "Ravana jumping down and placing his twenty muscular arms under the massive mountain, trying to lift it, 9:16", "approx_sec": 6.0}, {"slide_index": 5, "caption": "पर्वत हिलने लगा!", "image_prompt": "The entire Mount Kailash shaking, rocks falling, causing a massive earthquake in the region, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "शिव जी ने मुस्कुराकर अपना अंगूठा दबाया।", "image_prompt": "Lord Shiva, sitting peacefully with Parvati, slightly pressing down his glowing big toe on the ground, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "रावण के हाथ बुरी तरह कुचले गए।", "image_prompt": "The massive mountain crashing back down, trapping and crushing Ravana''s multiple hands under the heavy rocks, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "वह दर्द से भयंकर चीखने लगा।", "image_prompt": "Ravana screaming in extreme agony, his ten faces showing intense pain, veins popping, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "उसे अपनी गलती का एहसास हुआ।", "image_prompt": "Ravana closing his eyes, realizing he challenged the supreme Lord Shiva, surrendering completely, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "उसने ''शिव तांडव स्तोत्र'' गाना शुरू किया।", "image_prompt": "Ravana using his trapped arms to play music on his own nerves, singing the rhythmic Tandava Stotram, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "भक्ति से प्रसन्न होकर शिव ने उसे माफ किया।", "image_prompt": "Lord Shiva appearing before the freed Ravana, looking pleased and blessing him with a glowing hand, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "और उसे ''चंद्रहास'' खड्ग भेंट की।", "image_prompt": "Lord Shiva giving Ravana a terrifying, glowing crescent moon-shaped sword (Chandrahas), 9:16", "approx_sec": 5.0}]}' WHERE id = 'ravana_shiva_tandava';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "shabari_berries", "title": "शबरी के जूठे बेर", "category": "रामायण कथा", "script_hi": "भगवान राम ने शबरी के जूठे बेर क्यों खाए? शबरी एक भीलनी (आदिवासी) महिला थी, जो मातंग ऋषि के आश्रम में रहती थी। ऋषि ने प्राण त्यागने से पहले शबरी को वरदान दिया था कि एक दिन स्वयं भगवान राम उससे मिलने उसकी कुटिया में आएंगे। इस विश्वास के साथ शबरी हज़ारों दिनों तक रोज़ जंगल का रास्ता साफ करती और ताज़े मीठे बेर चुनकर लाती। बेर मीठे हैं या खट्टे, यह जांचने के लिए वह हर एक बेर को थोड़ा सा चखकर (जूठा करके) रखती थी। कई सालों के इंतज़ार के बाद, जब शबरी अत्यंत बूढ़ी हो गई, तब अंततः श्री राम लक्ष्मण के साथ सीता माता की खोज करते हुए वहां पहुंचे। शबरी की खुशी का ठिकाना नहीं रहा। उसने प्रेम भाव से अपने चखे हुए जूठे बेर राम को दिए। लक्ष्मण जी यह देखकर अचंभित रह गए और उन्होंने जूठे बेर खाने से मना कर दिया। लेकिन श्री राम, जो केवल सच्ची भक्ति के भूखे हैं, ने बड़े प्रेम और आनंद से उन जूठे बेरों को खाया। यह कथा हमें सिखाती है कि भगवान के लिए ना कोई जात-पात है, ना छुआछूत; वे केवल मन का सच्चा भाव देखते हैं।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "भगवान राम ने शबरी के जूठे बेर क्यों खाए?", "image_prompt": "Lord Rama smiling warmly while eating a small wild berry (ber) from a leaf plate held by an old tribal woman, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "शबरी मातंग ऋषि के आश्रम में रहती थी।", "image_prompt": "Young tribal woman Shabari respectfully serving an old, wise sage (Matanga Rishi) in a simple forest ashram, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "ऋषि ने कहा था, ''राम तुमसे मिलने आएंगे।''", "image_prompt": "The dying sage blessing Shabari, pointing towards the path with a glowing hand, instilling deep faith, 9:16", "approx_sec": 6.0}, {"slide_index": 4, "caption": "वह रोज़ राम के इंतज़ार में रास्ता साफ करती।", "image_prompt": "Old Shabari diligently sweeping the dirt path with a broom made of leaves, eagerly waiting, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "और रोज़ ताज़े मीठे बेर चुनकर लाती।", "image_prompt": "Old Shabari carefully picking wild berries from bushes in the forest, holding a small woven basket, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "बेर मीठे हों, इसलिए वह उन्हें चखकर रखती।", "image_prompt": "Shabari taking a small bite of a berry, checking if it is sweet, and putting the good ones in a bowl, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "सालों बाद, अंततः राम और लक्ष्मण वहां पहुंचे।", "image_prompt": "Lord Rama and Lakshmana, carrying their bows, walking towards Shabari''s humble hut, divine glow, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "शबरी की खुशी का ठिकाना नहीं रहा।", "image_prompt": "Shabari falling to her knees with tears of extreme joy flowing from her eyes upon seeing Lord Rama, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "उसने प्रेम से अपने जूठे बेर परोसे।", "image_prompt": "Shabari lovingly offering the bowl of pre-tasted berries to Lord Rama with trembling, devoted hands, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "लक्ष्मण जी यह देखकर अचंभित रह गए।", "image_prompt": "Lakshmana looking shocked and hesitant, refusing to eat the half-bitten berries, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "लेकिन राम ने बड़े आनंद से उन्हें खाया।", "image_prompt": "Lord Rama eating the berry with closed eyes, showing an expression of extreme satisfaction and bliss, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "भगवान केवल मन का सच्चा भाव देखते हैं।", "image_prompt": "A glowing lotus floating in a simple clay bowl, symbolizing pure devotion over social status, 9:16", "approx_sec": 5.0}]}' WHERE id = 'shabari_berries';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "setu_bandhan_squirrel", "title": "राम सेतु और छोटी गिलहरी", "category": "रामायण कथा", "script_hi": "राम सेतु के निर्माण में एक छोटी सी गिलहरी का क्या योगदान था? जब श्री राम की वानर सेना लंका जाने के लिए समुद्र पर विशाल पत्थरों से राम सेतु बना रही थी, तब बड़े-बड़े वानर और भालू भारी-भरकम चट्टानें और पहाड़ उठाकर समुद्र में डाल रहे थे। उस समय एक छोटी सी गिलहरी भी राम की भक्ति में वहां आ गई। वह पहले समुद्र के पानी में जाकर गीली होती, फिर रेत में लेट जाती जिससे रेत उसके शरीर पर चिपक जाती, और फिर पुल पर जाकर उस रेत को झाड़ देती थी। गिलहरी बार-बार ऐसा कर रही थी, ताकि पत्थरों के बीच की दरारें भर जाएं। कुछ वानरों ने उसे देखकर मज़ाक उड़ाया और कहा कि तेरी चुटकी भर रेत से यह महासागर कैसे पटेगा? जब श्री राम ने यह देखा, तो उन्होंने वानरों को रोका। भगवान राम ने उस छोटी सी गिलहरी को अपने हाथ में उठाया और प्यार से उसकी पीठ पर अपनी तीन उंगलियां फेरीं। कहते हैं कि आज भी गिलहरियों की पीठ पर जो तीन सफेद धारियां होती हैं, वो भगवान राम के उंगलियों के ही निशान हैं! यह कथा बताती है कि सेवा का आकार नहीं, बल्कि उसके पीछे का समर्पण और भाव मायने रखता है।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "राम सेतु बनाने में गिलहरी का क्या योगदान था?", "image_prompt": "A cute little Indian palm squirrel holding a tiny pebble, standing in front of the massive ocean, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "वानर सेना समुद्र पर विशाल सेतु बना रही थी।", "image_prompt": "Giant muscular Vanaras (monkey warriors) throwing massive boulders with ''Rama'' written on them into the sea, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "एक छोटी सी गिलहरी भी वहां आ गई।", "image_prompt": "The tiny squirrel looking up with deep devotion at the giant boulders being placed in the water, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "वह पहले समुद्र के पानी में गीली होती...", "image_prompt": "The small squirrel dipping itself into the ocean waves, getting its fur completely wet, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "फिर रेत में लेटकर रेत चिपकाती।", "image_prompt": "The wet squirrel rolling around in the golden beach sand, covering itself completely in sand, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "और पुल पर जाकर रेत को झाड़ देती।", "image_prompt": "The sandy squirrel standing on the massive rocks of the bridge, vigorously shaking the sand into the gaps, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "ताकि पत्थरों के बीच की दरारें भर जाएं।", "image_prompt": "Close up of the tiny sand grains filling the small gaps between the giant floating boulders, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "वानरों ने उसका मज़ाक उड़ाया।", "image_prompt": "A giant monkey warrior laughing and pointing a finger at the tiny squirrel, mocking its small effort, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "श्री राम ने वानरों को रोका।", "image_prompt": "Lord Rama standing tall, gently raising his hand to stop the monkeys from mocking, showing kindness, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "उन्होंने गिलहरी को प्यार से हाथ में उठाया।", "image_prompt": "Lord Rama holding the tiny sandy squirrel tenderly in his glowing lotus-like hands, smiling warmly, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "और उसकी पीठ पर अपनी उंगलियां फेरीं।", "image_prompt": "Lord Rama gently stroking the squirrel''s back with his three fingers, leaving three glowing white stripes, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "सेवा का आकार नहीं, समर्पण मायने रखता है।", "image_prompt": "A close up of a beautiful squirrel with three distinct stripes on its back, sitting near a floating stone, 9:16", "approx_sec": 5.0}]}' WHERE id = 'setu_bandhan_squirrel';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "krishna_birth", "title": "श्री कृष्ण का जन्म और कारागार", "category": "विष्णु पुराण", "script_hi": "भगवान श्री कृष्ण ने एक अंधेरी जेल में जन्म क्यों लिया? मथुरा का क्रूर राजा कंस अपनी बहन देवकी से बहुत प्रेम करता था। लेकिन जब देवकी का विवाह वासुदेव से हुआ, तो आकाशवाणी हुई कि देवकी का आठवां पुत्र ही कंस की मृत्यु का कारण बनेगा। मौत के डर से कांपते हुए कंस ने तुरंत अपनी बहन और बहनोई को एक अंधेरी कालकोठरी में डाल दिया और उनके एक-एक करके 7 बच्चों को बेरहमी से मार डाला। जब भाद्रपद मास की अष्टमी की आधी रात को आठवें पुत्र के रूप में श्री कृष्ण का जन्म हुआ, तो चमत्कार होने लगे। कालकोठरी में अचानक दिव्य प्रकाश फैल गया, जेल के सारे ताले अपने आप खुल गए और सभी पहरेदार गहरी नींद में सो गए। वासुदेव ने तुरंत नवजात कृष्ण को एक टोकरी में रखा और उफनती हुई यमुना नदी को पार करके उन्हें गोकुल में सुरक्षित नंद बाबा के घर छोड़ आए। यह कथा हमें सिखाती है कि चाहे बुराई कितनी भी ताकतवर क्यों न हो, जब भगवान आते हैं तो हर ताला और हर बेड़ी अपने आप टूट जाती है।", "estimated_speech_sec": 90.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "श्री कृष्ण ने एक अंधेरी जेल में जन्म क्यों लिया?", "image_prompt": "A dark, ancient stone dungeon with heavy iron bars, mysterious glowing blue light inside, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "कंस ने देवकी और वासुदेव को जेल में डाल दिया।", "image_prompt": "Cruel king Kansa pointing an angry finger, chaining Devaki and Vasudeva in a dark dungeon, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "आकाशवाणी थी कि आठवां पुत्र कंस को मारेगा।", "image_prompt": "King Kansa looking terrified as a divine lightning storm forms a face in the night sky, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "कंस ने उनके 7 बच्चों को मार डाला।", "image_prompt": "Devaki crying in the dark dungeon holding an empty blanket, immense sorrow, heavy chains, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "अष्टमी की आधी रात को चमत्कार हुआ।", "image_prompt": "A brilliant, blinding golden light suddenly filling the dark dungeon, baby Krishna appearing, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "श्री कृष्ण का जन्म हुआ।", "image_prompt": "Vasudeva and Devaki kneeling respectfully before the glowing, divine baby Lord Krishna with four arms, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "जेल के ताले अपने आप खुल गए।", "image_prompt": "Heavy iron padlocks glowing magically and breaking open on their own, dropping to the floor, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "सभी पहरेदार गहरी नींद में सो गए।", "image_prompt": "Fierce demon guards lying on the floor in a deep magical slumber, completely unaware, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "वासुदेव ने कृष्ण को टोकरी में रखा।", "image_prompt": "Vasudeva gently placing the glowing baby in a wicker basket on his head, heavy rain falling, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "और उफनती यमुना नदी पार की।", "image_prompt": "Vasudeva walking through the flooded, raging Yamuna river at night, the giant snake Sheshnaag providing an umbrella, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "कृष्ण को गोकुल में सुरक्षित छोड़ आए।", "image_prompt": "Vasudeva secretly placing baby Krishna next to a sleeping Yashoda in a cozy village house, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "भगवान के आने पर हर बेड़ी टूट जाती है।", "image_prompt": "A broken iron chain lying on the floor next to a blooming glowing blue lotus, symbol of freedom, 9:16", "approx_sec": 5.0}]}' WHERE id = 'krishna_birth';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "putana_salvation", "title": "पूतना का उद्धार", "category": "विष्णु पुराण", "script_hi": "श्री कृष्ण ने बाल रूप में ही भयंकर राक्षसी पूतना का वध कैसे किया? गोकुल में श्री कृष्ण के जन्म की खबर सुनकर राजा कंस बौखला गया। उसने नवजात बच्चों को मारने के लिए ''पूतना'' नाम की एक बेहद खतरनाक और मायावी राक्षसी को भेजा। पूतना एक अत्यंत सुंदर और ममतामयी स्त्री का रूप धारण करके गोकुल पहुंची। उसने अपने स्तनों (छाती) पर एक अत्यंत भयंकर और जानलेवा विष (ज़हर) लगा रखा था, ताकि दूध पिलाते ही बच्चा मर जाए। कोई उसे पहचान नहीं पाया और उसने माता यशोदा से आज्ञा लेकर बाल कृष्ण को गोद में उठा लिया। पूतना ने प्यार का नाटक करते हुए कृष्ण को विषैला दूध पिलाना शुरू किया। लेकिन भगवान को कौन मार सकता है? बाल कृष्ण ने दूध के साथ-साथ पूतना के प्राण भी चूस लिए! पूतना दर्द से चीखने लगी और वह अपने असली, भयंकर राक्षसी रूप में वापस आ गई। विशाल राक्षसी ज़मीन पर गिरकर मर गई, लेकिन खेलते हुए बाल कृष्ण उसकी छाती पर बिल्कुल सुरक्षित थे। भगवान ने पूतना को इसलिए मोक्ष दिया, क्योंकि उसने एक पल के लिए ही सही, लेकिन माँ (माता) का रूप धारण किया था।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "बाल कृष्ण ने राक्षसी पूतना का वध कैसे किया?", "image_prompt": "A beautiful but eerie woman with a fake sweet smile entering a vibrant Indian village, carrying hidden darkness, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "कंस ने पूतना राक्षसी को गोकुल भेजा।", "image_prompt": "King Kansa secretly ordering a giant terrifying demoness (Putana) in a dark corner of his palace, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "पूतना ने एक सुंदर स्त्री का रूप धारण किया।", "image_prompt": "The terrifying demoness magically transforming into a gorgeous, richly dressed motherly woman, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "उसने अपने शरीर पर भयंकर विष लगा रखा था।", "image_prompt": "A glowing green toxic aura radiating slightly from the woman''s chest, hidden by her beautiful clothes, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "उसने यशोदा से आज्ञा लेकर कृष्ण को गोद में लिया।", "image_prompt": "Putana holding glowing baby Krishna lovingly in her arms, Yashoda looking on innocently, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "पूतना ने कृष्ण को विषैला दूध पिलाना शुरू किया।", "image_prompt": "Baby Krishna drinking the milk with his eyes closed playfully, immune to the dark green poison entering him, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "लेकिन कृष्ण ने उसके प्राण चूस लिए!", "image_prompt": "Putana''s beautiful face suddenly twisting in immense pain and horror, gasping for air, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "वह दर्द से चीखने लगी।", "image_prompt": "Putana screaming loudly, her disguise fading away, revealing her terrifying, huge demon skin, 9:16", "approx_sec": 5.0}, {"slide_index": 9, "caption": "पूतना अपने भयंकर राक्षसी रूप में आ गई।", "image_prompt": "A gigantic, scary demoness crashing through the trees and falling heavily to the ground, causing an earthquake, 9:16", "approx_sec": 6.0}, {"slide_index": 10, "caption": "विशाल राक्षसी मर गई, पर कृष्ण सुरक्षित थे।", "image_prompt": "Baby Krishna crawling happily and playing on the massive fallen demoness, completely unharmed and glowing, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "कृष्ण ने पूतना को भी मोक्ष दिया।", "image_prompt": "A glowing, pure soul leaving the giant demon body and travelling towards the divine heavens, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "क्योंकि उसने एक पल के लिए ही सही, माँ का रूप लिया था।", "image_prompt": "Lord Krishna playfully smiling, a divine peacock feather glowing on his head, representing pure unconditional grace, 9:16", "approx_sec": 5.0}]}' WHERE id = 'putana_salvation';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "govardhan_puja", "title": "गोवर्धन पर्वत और इंद्र का कोप", "category": "विष्णु पुराण", "script_hi": "श्री कृष्ण ने अपनी छोटी उंगली पर गोवर्धन पर्वत क्यों उठाया था? गोकुल के लोग हर साल बारिश के देवता, इंद्र की पूजा करते थे ताकि अच्छी बारिश हो और फसल अच्छी हो। लेकिन बाल कृष्ण ने लोगों को समझाया कि इंद्र केवल अपना काम कर रहे हैं। हमें इंद्र के बजाय ''गोवर्धन पर्वत'' की पूजा करनी चाहिए, जो हमारी गायों को चारा और हमें पानी देता है। गोकुलवासियों ने कृष्ण की बात मान ली और इंद्र की पूजा बंद कर दी। जब इंद्र देव को यह बात पता चली, तो उनके अहंकार को गहरी ठेस पहुंची। गुस्से में आकर इंद्र ने गोकुल पर भयंकर तूफ़ान और प्रलयंकारी बारिश शुरू कर दी। पूरा गांव डूबने लगा और लोग घबरा गए। तब श्री कृष्ण ने अपने चमत्कार से विशाल गोवर्धन पर्वत को अपनी बायीं हाथ की सबसे छोटी उंगली (कनिष्ठा) पर उठा लिया! सभी गांव वालों और जानवरों ने उस विशाल पर्वत के नीचे शरण ली। 7 दिन और 7 रात तक लगातार बारिश होती रही, लेकिन कृष्ण ने पर्वत को हिलने तक नहीं दिया। अंततः इंद्र का अहंकार टूट गया, वे कृष्ण के चरणों में गिर पड़े और क्षमा मांगी।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कृष्ण ने छोटी उंगली पर गोवर्धन पर्वत क्यों उठाया?", "image_prompt": "Young boy Krishna balancing a massive, glowing mountain on his pinky finger effortlessly, smiling warmly, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "गोकुल के लोग इंद्र की पूजा करते थे।", "image_prompt": "Villagers of Gokul offering lots of food and sweets to a statue of Lord Indra, hoping for rain, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "कृष्ण ने कहा, गोवर्धन पर्वत की पूजा करो।", "image_prompt": "Young Krishna pointing towards the lush green Govardhan mountain, surrounded by happy cows, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "इंद्र देव के अहंकार को ठेस पहुंची।", "image_prompt": "Lord Indra looking furious in the heavens, sitting on his white elephant, holding his lightning bolt, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "इंद्र ने भयंकर तूफ़ान और प्रलयंकारी बारिश शुरू कर दी।", "image_prompt": "Apocalyptic black storm clouds, heavy rain, and fierce lightning striking the helpless village of Gokul, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "पूरा गांव डूबने लगा।", "image_prompt": "Panicking villagers and cows trying to find shelter as floodwaters rise rapidly around their mud houses, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "तब श्री कृष्ण ने विशाल पर्वत उठा लिया!", "image_prompt": "Krishna magically lifting the entire massive Govardhan mountain from its base, glowing divine aura, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "सभी गांव वालों ने पर्वत के नीचे शरण ली।", "image_prompt": "Hundreds of villagers and cows standing safely under the giant floating mountain, looking at Krishna in awe, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "7 दिन और 7 रात तक लगातार बारिश हुई।", "image_prompt": "Furious storm continuing outside, but inside under the mountain it is completely dry, warm, and safe, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "कृष्ण ने पर्वत को हिलने तक नहीं दिया।", "image_prompt": "Close up of young Krishna''s little pinky finger effortlessly holding up millions of tons of solid rock, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "अंततः इंद्र का अहंकार टूट गया।", "image_prompt": "The rain stopping, sunlight piercing the clouds, Lord Indra realizing his terrible mistake and arrogance, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "इंद्र ने कृष्ण के चरणों में गिरकर क्षमा मांगी।", "image_prompt": "Lord Indra bowing down, touching the small feet of Lord Krishna, completely humbled, divine peace, 9:16", "approx_sec": 6.0}]}' WHERE id = 'govardhan_puja';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "kalia_mardan", "title": "कालिया नाग का मर्दन", "category": "विष्णु पुराण", "script_hi": "बाल कृष्ण ने कालिया नाग के हज़ार फनों पर नृत्य क्यों किया? यमुना नदी के एक बहुत गहरे हिस्से में कालिया नाम का एक भयंकर और अत्यंत विषैला नाग अपने परिवार के साथ आकर रहने लगा था। कालिया नाग के ज़हर की गर्मी और तीव्रता इतनी अधिक थी कि नदी का पानी खौलने लगा था और वहां जाने वाले सभी पक्षी, जानवर और इंसान मर जाते थे। एक दिन, कृष्ण अपने ग्वाल-बालों (दोस्तों) के साथ वहां गेंद खेल रहे थे। अचानक उनकी गेंद पानी में गिर गई। सभी ने कृष्ण को रोका, लेकिन कृष्ण तुरंत एक ऊंचे पेड़ से उस ज़हरीली नदी में कूद गए। पानी के अंदर कालिया नाग ने कृष्ण को अपने खतरनाक कुंडलियों में जकड़ लिया। लेकिन बाल कृष्ण ने अपने शरीर का आकार इतना बड़ा कर लिया कि नाग की पकड़ छूट गई। इसके बाद, कृष्ण ने छलांग लगाई और कालिया नाग के विशाल फनों पर खड़े हो गए। कालिया नाग ने जितने फन उठाए, कृष्ण ने अपनी बांसुरी बजाते हुए उन पर नृत्य करके उन्हें कुचल दिया। नाग की पत्नियों ने कृष्ण से दया की भीख मांगी। कृष्ण ने कालिया को माफ कर दिया और उसे यमुना छोड़कर समुद्र में जाने का आदेश दिया।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कृष्ण ने कालिया नाग के फनों पर नृत्य क्यों किया?", "image_prompt": "Young boy Krishna gracefully dancing on the multiple glowing heads of a giant dark serpent in a river, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "यमुना नदी में कालिया नाग रहने लगा था।", "image_prompt": "A terrifying, massive multi-headed black serpent (Kaliya) swimming in the Yamuna river, looking evil, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "नाग के ज़हर से नदी का पानी खौलने लगा था।", "image_prompt": "The river water bubbling, turning dark green with poison, dead fish and birds floating on the surface, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "एक दिन कृष्ण की गेंद पानी में गिर गई।", "image_prompt": "Young Krishna and his cowherd friends looking worried as a small ball splashes into the toxic river, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "कृष्ण ऊंचे पेड़ से उस ज़हरीली नदी में कूद गए!", "image_prompt": "Young Krishna fearlessly diving off a high Kadamba tree branch directly into the dark poisonous water, 9:16", "approx_sec": 6.0}, {"slide_index": 6, "caption": "कालिया नाग ने कृष्ण को जकड़ लिया।", "image_prompt": "The giant serpent fiercely wrapping its thick coils tightly around young Krishna underwater, toxic bubbles, 9:16", "approx_sec": 5.0}, {"slide_index": 7, "caption": "कृष्ण ने अपने शरीर का आकार बड़ा कर लिया।", "image_prompt": "Krishna expanding his divine form, forcing the giant snake to release its grip in pain, glowing light, 9:16", "approx_sec": 6.0}, {"slide_index": 8, "caption": "कृष्ण ने छलांग लगाई और नाग के फनों पर खड़े हो गए।", "image_prompt": "Krishna jumping high out of the water and landing perfectly on the giant extended hoods of the serpent, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "बांसुरी बजाते हुए फनों को कुचल दिया।", "image_prompt": "Krishna playing his flute with one hand and dancing vigorously, stomping down the snake''s heads, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "नाग की पत्नियों ने दया की भीख मांगी।", "image_prompt": "The snake wives (Naginis) rising from the water with folded hands, begging Krishna to spare their husband, 9:16", "approx_sec": 5.0}, {"slide_index": 11, "caption": "कृष्ण ने कालिया को समुद्र में जाने का आदेश दिया।", "image_prompt": "Lord Krishna pointing a commanding finger, ordering the defeated snake to leave the river forever, 9:16", "approx_sec": 6.0}, {"slide_index": 12, "caption": "यमुना का पानी फिर से शुद्ध हो गया।", "image_prompt": "The Yamuna river returning to a sparkling, crystal clear blue, lotuses blooming, peaceful nature, 9:16", "approx_sec": 5.0}]}' WHERE id = 'kalia_mardan';
UPDATE topic_catalog SET pregenerated_json = '{"story_id": "sudama_rice", "title": "सुदामा के चावल", "category": "विष्णु पुराण", "script_hi": "भगवान श्री कृष्ण और सुदामा की मित्रता की कहानी इतनी खास क्यों है? सुदामा एक बहुत ही गरीब ब्राह्मण थे और बचपन में कृष्ण के सहपाठी थे। कई सालों बाद, जब सुदामा के परिवार के पास खाने के लिए कुछ नहीं बचा, तो उनकी पत्नी ने उन्हें द्वारकाधीश कृष्ण से मदद मांगने भेजा। सुदामा संकोच में थे, कि द्वारका का राजा उन्हें पहचानेगा भी या नहीं? भेंट के लिए उनकी पत्नी ने पड़ोसियों से मांगकर थोड़ी सी सूखी ''पोहे'' (चावल) एक फटे हुए कपड़े में बांधकर दी। जब सुदामा द्वारका के शानदार महल पहुंचे, तो उनके फटे कपड़े देखकर पहरेदारों ने उन्हें रोक लिया। लेकिन जैसे ही कृष्ण ने सुदामा का नाम सुना, वे नंगे पैर दौड़ते हुए गेट पर आ गए! उन्होंने सुदामा को गले लगाया, उन्हें अपने सिंहासन पर बैठाया और अपने आंसुओं से उनके पैर धोए। सुदामा को अपनी गरीब भेंट (चावल) देने में शर्म आ रही थी, लेकिन कृष्ण ने उसे छीनकर बड़े प्रेम से खाया। सुदामा ने बिना कुछ मांगे विदाई ली। लेकिन जब वे अपने गांव लौटे, तो उन्होंने देखा कि उनकी टूटी झोपड़ी एक सोने के महल में बदल चुकी थी! भगवान अपने सच्चे मित्र को बिना मांगे ही सब कुछ दे देते हैं।", "estimated_speech_sec": 95.0, "part_info": {"current_part": 1, "total_parts": 1}, "slides": [{"slide_index": 1, "caption": "कृष्ण और सुदामा की मित्रता इतनी खास क्यों है?", "image_prompt": "Lord Krishna and poor Sudama embracing each other tightly, glowing divine friendship, highly emotional, 9:16", "approx_sec": 5.0}, {"slide_index": 2, "caption": "सुदामा एक बहुत ही गरीब ब्राह्मण थे।", "image_prompt": "Sudama sitting in a broken, leaky mud hut, wearing torn clothes, looking thin and very poor, 9:16", "approx_sec": 5.0}, {"slide_index": 3, "caption": "उनकी पत्नी ने सूखी चावल की पोटली दी।", "image_prompt": "Sudama''s wife sadly tying a handful of dry puffed rice (poha) into a torn, dirty piece of cloth, 9:16", "approx_sec": 5.0}, {"slide_index": 4, "caption": "सुदामा द्वारका के शानदार महल पहुंचे।", "image_prompt": "Poor Sudama standing in awe outside the massive, glowing, golden gates of Dwarka palace, 9:16", "approx_sec": 5.0}, {"slide_index": 5, "caption": "पहरेदारों ने उन्हें रोक लिया।", "image_prompt": "Heavily armored royal guards blocking poor Sudama with their spears, looking at him with suspicion, 9:16", "approx_sec": 5.0}, {"slide_index": 6, "caption": "लेकिन कृष्ण नंगे पैर दौड़ते हुए आए!", "image_prompt": "Lord Krishna in royal attire, completely ignoring protocol, running barefoot desperately towards the palace gate, 9:16", "approx_sec": 6.0}, {"slide_index": 7, "caption": "उन्होंने सुदामा को गले लगा लिया।", "image_prompt": "King Krishna hugging the poor, dirty beggar Sudama tightly, tears flowing from Krishna''s eyes, 9:16", "approx_sec": 5.0}, {"slide_index": 8, "caption": "कृष्ण ने आंसुओं से उनके पैर धोए।", "image_prompt": "Krishna making Sudama sit on the royal throne and washing Sudama''s blistered feet with a golden pot, 9:16", "approx_sec": 6.0}, {"slide_index": 9, "caption": "सुदामा को चावल देने में शर्म आ रही थी।", "image_prompt": "Sudama trying to hide the small torn pouch of dry rice behind his back, feeling deeply ashamed, 9:16", "approx_sec": 5.0}, {"slide_index": 10, "caption": "कृष्ण ने छीनकर बड़े प्रेम से खाया।", "image_prompt": "Lord Krishna playfully snatching the pouch and eating a handful of dry rice with immense joy and bliss, 9:16", "approx_sec": 6.0}, {"slide_index": 11, "caption": "सुदामा ने बिना कुछ मांगे विदाई ली।", "image_prompt": "Sudama walking back on the forest path, empty-handed but smiling, completely content just seeing his friend, 9:16", "approx_sec": 5.0}, {"slide_index": 12, "caption": "उनका गांव सोने के महल में बदल चुका था!", "image_prompt": "Sudama looking shocked as his broken hut is now a magnificent golden palace filled with wealth, divine grace, 9:16", "approx_sec": 5.0}]}' WHERE id = 'sudama_rice';
